'use client';

import { useCallback, useEffect, useMemo, useRef } from 'react';

import { useIsNarrow } from '@/registry/ndeko/hooks/use-is-narrow';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { InlineSheet } from '@/registry/ndeko/ui/inline-sheet';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { CanvasPanel } from './canvas-panel';
import { capitalized } from './capitalized';
import { faceKeyOf, placementOf, structureKeyOf } from './flow';
import { Inspector } from './inspector';
import { layoutOf } from './layout';
import type { Workflow } from './model';
import { Palette } from './palette';
import { isBusy } from './run';
import { holdsForRun, LOOP_AFTER_MS, RESTING, SCRIPT } from './script';
import { hasUnsavedChanges, INITIAL, reducer } from './session';
import { TopBar } from './top-bar';
import {
  paletteTargetOf,
  useBuilderHandlers,
  type Backend,
} from './use-builder-handlers';
import { useKept } from './use-kept';
import { useRunClock } from './use-run-clock';
import { useViewport } from './use-viewport';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
  holdWhile: holdsForRun,
};

/** The width of the `@3xl` container variant: under it the inspector lives in a sheet. */
const INSPECTOR_SHEET_BELOW_REM = 48;

/** The width of the `@5xl` container variant: under it the palette lives in a sheet and the mini map is gone. */
const PALETTE_SHEET_BELOW_REM = 64;

/**
 * Nothing calls a network. A real backend plugs in here: a test run with its sample, a save, a
 * publish, the answer of a person to a step that asks first, and every change made to the flow.
 */
export type Application14Props = Backend & {
  onChange?: (workflow: Workflow) => void;
};

export default function Application14({
  onRun,
  onSave,
  onPublish,
  onApprove,
  onDeny,
  onChange,
}: Application14Props) {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
    takeOver,
  } = useSession(SESSION);
  const reported = useRef(state.workflow);
  const hasInspectorSheet = useIsNarrow(ref, INSPECTOR_SHEET_BELOW_REM);
  const hasPaletteSheet = useIsNarrow(ref, PALETTE_SHEET_BELOW_REM);
  const { workflow, run, selectedId } = state;
  const shownFlow = useKept(workflow, faceKeyOf(workflow));
  const structure = useKept(workflow, structureKeyOf(workflow));
  const layout = useMemo(() => layoutOf(structure), [structure]);
  const backend = { onRun, onSave, onPublish, onApprove, onDeny };
  const {
    echo,
    mintId,
    pickEntry,
    select,
    leaveInspector,
    openInspector,
    openPalette,
    closePalette,
    remove,
    duplicate,
    insert,
    renameStep,
    renameWorkflow,
    undo,
    redo,
    undoFromNotice,
    undoFromKeys,
    redoFromKeys,
    save,
    publish,
    startRun,
    runAgain,
    clearRun,
    decide,
  } = useBuilderHandlers(ref, {
    state,
    act,
    hasInspectorSheet,
    hasPaletteSheet,
    backend,
  });

  const deselect = useCallback(() => {
    act({ type: 'selected', id: null });
  }, [act]);

  const viewport = useViewport(layout, deselect, takeOver);

  const advanceRun = useCallback(
    (token: number, beat: number) => {
      act({ type: 'runAdvanced', token, beat });
    },
    [act]
  );

  useRunClock(run, workflow, isInView, advanceRun);

  /** The demonstration edits the sample flow on its own: only what a person changes is reported. */
  useEffect(() => {
    const hasChanged = reported.current !== workflow;
    reported.current = workflow;
    if (hasChanged && !isAutoplaying) {
      onChange?.(workflow);
    }
  }, [workflow, isAutoplaying, onChange]);

  const isPaletteShown = hasPaletteSheet && state.isPaletteOpen;
  const isInspectorShown = hasInspectorSheet && state.isInspectorOpen;
  const isBehindSheet = isPaletteShown || isInspectorShown;
  const canReplay = isFinished && !isAutoplaying;
  const message = spokenUnless(isAutoplaying, state.spoken);
  const paletteTarget = paletteTargetOf(selectedId);
  const palettePlace = placementOf(workflow, paletteTarget);
  const placement = capitalized(palettePlace);

  const inspector = {
    workflow,
    savedWorkflow: state.savedWorkflow,
    selectedId,
    tab: state.tab,
    run,
    isActive: isInView,
    onAct: act,
    onMintId: mintId,
    onLeave: leaveInspector,
  };

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-sidebar text-foreground @container/app min-h-dvh w-full'
      >
        <div className='relative flex h-dvh min-h-[40rem] flex-col overflow-hidden'>
          <div inert={isBehindSheet} className='flex min-h-0 flex-1 flex-col'>
            <TopBar
              workflow={shownFlow}
              save={state.save}
              hasUnsavedChanges={hasUnsavedChanges(state)}
              isLive={state.isLive}
              isRunning={isBusy(run)}
              pressed={pressed}
              canReplay={canReplay}
              onReplay={restart}
              onRename={renameWorkflow}
              onSave={save}
              onPublish={publish}
              onRun={runAgain}
            />
            <div className='flex min-h-0 flex-1 gap-2 @3xl/app:px-2 @3xl/app:pb-2'>
              <aside
                aria-label='Steps to add'
                className='hidden w-56 shrink-0 px-1 pt-1 @5xl/app:flex'
              >
                {!hasPaletteSheet && (
                  <Palette
                    placement={placement}
                    pressed={pressed}
                    onPick={pickEntry}
                  />
                )}
              </aside>
              <CanvasPanel
                state={state}
                shownFlow={shownFlow}
                layout={layout}
                viewport={viewport}
                pressed={pressed}
                echo={echo}
                hasMiniMap={!hasPaletteSheet}
                onSelect={select}
                onRemove={remove}
                onDuplicate={duplicate}
                onInsert={insert}
                onDecide={decide}
                onRename={renameStep}
                onUndo={undo}
                onRedo={redo}
                onUndoNotice={undoFromNotice}
                onUndoKey={undoFromKeys}
                onRedoKey={redoFromKeys}
                onRun={startRun}
                onClearRun={clearRun}
                onOpenPalette={openPalette}
                onOpenInspector={openInspector}
              />
              <aside
                aria-label='Setup of the selected step'
                className='hidden w-72 shrink-0 @3xl/app:flex @6xl/app:w-80'
              >
                <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex min-h-0 min-w-0 flex-1 rounded-xl p-3 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
                  {!hasInspectorSheet && (
                    <Inspector {...inspector} className='w-full' />
                  )}
                </div>
              </aside>
            </div>
          </div>

          <InlineSheet
            name='palette'
            label='Add a step'
            closeLabel='Close the palette'
            side='start'
            isOpen={isPaletteShown}
            className='@5xl/app:hidden'
            panelClassName='bg-sidebar gap-1 p-3'
            onClose={closePalette}
          >
            {hasPaletteSheet && (
              <Palette
                placement={placement}
                pressed={pressed}
                onPick={pickEntry}
                className='flex-1'
              />
            )}
          </InlineSheet>
          <InlineSheet
            name='inspector'
            label='Step setup'
            closeLabel='Close the step setup'
            side='bottom'
            isOpen={isInspectorShown}
            className='@3xl/app:hidden'
            panelClassName='bg-sidebar h-[80%] gap-1 p-3'
            onClose={leaveInspector}
          >
            {hasInspectorSheet && (
              <Inspector {...inspector} className='flex-1' />
            )}
          </InlineSheet>
          <LiveRegion message={message} />
        </div>
      </div>
    </ClockGate>
  );
}

'use client';

import { memo } from 'react';

import { WordRoll } from '@/components/core/word-roll';
import { useNow } from '@/registry/ndeko/hooks/use-agent-run';
import {
  pressedQuietOf,
  pressedSolidOf,
} from '@/registry/ndeko/lib/demonstration';
import { EllipsisIcon, PlayIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { countOf } from '@/registry/ndeko/lib/words';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { BRAND } from './data';
import { countsOf } from './flow';
import type { Workflow } from './model';
import { NameField } from './name-field';
import type { SaveState } from './session';

const MINUTE_MS = 60_000;

/** How often the line "Saved 3 min ago" looks at the time. */
const SAVED_TICK_MS = 15_000;

type SaveKind = 'saving' | 'unsaved' | 'saved';

const SAVE_DOT: Record<SaveKind, string> = {
  saving: 'bg-info animate-pulse',
  unsaved: 'bg-warning',
  saved: 'bg-success',
};

const RUN_LABELS: Record<MorphState, string> = {
  idle: 'Test run',
  busy: 'Running',
  done: 'Test run',
};

function saveKindOf(save: SaveState, hasUnsavedChanges: boolean): SaveKind {
  if (save.status === 'saving') {
    return 'saving';
  }
  if (hasUnsavedChanges) {
    return 'unsaved';
  }
  return 'saved';
}

/** The save the sample data starts from has no time of its own: it reads as two minutes old. */
function savedLineOf(at: number | null, now: number) {
  if (at === null) {
    return 'Saved 2 min ago';
  }
  const elapsed = now - at;
  const minutes = Math.floor(elapsed / MINUTE_MS);
  if (minutes < 1) {
    return 'Saved just now';
  }
  return `Saved ${minutes} min ago`;
}

function saveLineOf(kind: SaveKind, at: number | null, now: number) {
  if (kind === 'saving') {
    return 'Saving';
  }
  if (kind === 'unsaved') {
    return 'Unsaved changes';
  }
  return savedLineOf(at, now);
}

type SaveMarkProps = {
  save: SaveState;
  hasUnsavedChanges: boolean;
};

/** Only this line reads the clock, and only once a save of this session has a time to count from. */
function SaveMark({ save, hasUnsavedChanges }: SaveMarkProps) {
  const kind = saveKindOf(save, hasUnsavedChanges);
  const isCounting = kind === 'saved' && save.at !== null;
  const now = useNow(SAVED_TICK_MS, isCounting);
  const line = saveLineOf(kind, save.at, now);

  return (
    <span className='flex shrink-0 items-center gap-1.5'>
      <span
        aria-hidden='true'
        className={cn(
          'size-1.5 shrink-0 rounded-full transition-colors duration-200',
          SAVE_DOT[kind]
        )}
      />
      <WordRoll text={line} />
    </span>
  );
}

function countsLineOf(workflow: Workflow) {
  const counts = countsOf(workflow);
  const steps = countOf(counts.steps, 'step', 'steps');
  if (counts.branches === 0) {
    return steps;
  }
  const branches = countOf(counts.branches, 'branch', 'branches');
  return `${steps}, ${branches}`;
}

function publishWordOf(isLive: boolean) {
  if (isLive) {
    return 'Live';
  }
  return 'Draft';
}

const PUBLISH_WORDS = ['Draft', 'Live'];

function trackOf(isLive: boolean) {
  if (isLive) {
    return 'bg-success';
  }
  return 'bg-foreground/20';
}

function thumbOf(isLive: boolean) {
  if (isLive) {
    return 'translate-x-2';
  }
  return 'translate-x-0';
}

type PublishSwitchProps = {
  isLive: boolean;
  onPublish: (isLive: boolean) => void;
  className?: string;
};

/** A button that is a switch: it reads Draft, a press makes it read Live, and the tool bar confirms it in words. */
function PublishSwitch({ isLive, onPublish, className }: PublishSwitchProps) {
  const word = publishWordOf(isLive);

  return (
    <Button
      type='button'
      variant='outline'
      size='sm'
      role='switch'
      aria-checked={isLive}
      aria-label={`${word}, publish the workflow`}
      onClick={() => onPublish(!isLive)}
      className={className}
    >
      <span
        aria-hidden='true'
        className={cn(
          'flex h-3 w-5 shrink-0 items-center rounded-full p-0.5 transition-colors duration-200',
          trackOf(isLive)
        )}
      >
        <span
          className={cn(
            'bg-primary-foreground size-2 rounded-full transition-[translate] duration-200 ease-(--ease-out-strong)',
            thumbOf(isLive)
          )}
        />
      </span>
      <WordRoll text={word} labels={PUBLISH_WORDS} />
    </Button>
  );
}

function runStateOf(isRunning: boolean): MorphState {
  if (isRunning) {
    return 'busy';
  }
  return 'idle';
}

type TopBarProps = {
  workflow: Workflow;
  save: SaveState;
  hasUnsavedChanges: boolean;
  isLive: boolean;
  isRunning: boolean;
  pressed: string | null;
  canReplay: boolean;
  onReplay: () => void;
  onRename: (name: string) => void;
  onSave: () => void;
  onPublish: (isLive: boolean) => void;
  onRun: () => void;
};

/** Under 640px of its own width, Save and Publish go into one menu and the counts move to a line of their own. */
export const TopBar = memo(function TopBar({
  workflow,
  save,
  hasUnsavedChanges,
  isLive,
  isRunning,
  pressed,
  canReplay,
  onReplay,
  onRename,
  onSave,
  onPublish,
  onRun,
}: TopBarProps) {
  const isSaving = save.status === 'saving';
  const canSave = hasUnsavedChanges && !isSaving;
  const isSavePressed = pressed === 'save';

  return (
    <header className='@container shrink-0 px-3 py-2'>
      <div className='flex flex-wrap items-center gap-x-3 gap-y-1'>
        <div className='flex min-w-0 flex-1 items-center gap-2.5 @[40rem]:max-w-[45%] @[40rem]:flex-none'>
          <CompanyMark seed={BRAND.name} size='lg' title={BRAND.name} />
          <h1 className='flex min-w-0 text-sm'>
            <NameField
              value={workflow.name}
              label='Workflow name'
              action='Rename the workflow'
              onRename={onRename}
            />
          </h1>
        </div>
        <p className='text-muted-foreground order-last flex w-full min-w-0 items-center gap-3 ps-9.5 text-xs @[40rem]:order-none @[40rem]:w-auto @[40rem]:flex-1 @[40rem]:ps-0'>
          <span className='min-w-0 truncate tabular-nums'>
            <WordRoll text={countsLineOf(workflow)} />
          </span>
          <SaveMark save={save} hasUnsavedChanges={hasUnsavedChanges} />
        </p>
        <div className='flex shrink-0 items-center gap-1.5'>
          <ReplayButton
            isShown={canReplay}
            onReplay={onReplay}
            label='Replay'
          />
          <Button
            type='button'
            variant='outline'
            size='sm'
            disabled={!canSave}
            onClick={onSave}
            className={cn(
              'hidden @[40rem]:inline-flex',
              pressedQuietOf(isSavePressed)
            )}
          >
            Save
          </Button>
          <PublishSwitch
            isLive={isLive}
            onPublish={onPublish}
            className='hidden @[40rem]:inline-flex'
          />
          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <Button
                  type='button'
                  variant='ghost'
                  size='icon-sm'
                  aria-label='More actions'
                  className={cn(
                    'text-muted-foreground @[40rem]:hidden',
                    pressedQuietOf(isSavePressed)
                  )}
                />
              }
            >
              <EllipsisIcon />
            </DropdownMenuTrigger>
            <DropdownMenuContent align='end' className='w-48'>
              <DropdownMenuItem disabled={!canSave} onClick={onSave}>
                Save
              </DropdownMenuItem>
              <DropdownMenuCheckboxItem
                checked={isLive}
                onCheckedChange={onPublish}
              >
                Live
              </DropdownMenuCheckboxItem>
            </DropdownMenuContent>
          </DropdownMenu>
          <MorphButton
            type='button'
            size='sm'
            state={runStateOf(isRunning)}
            labels={RUN_LABELS}
            idleIcon={<PlayIcon />}
            onClick={onRun}
            className={pressedSolidOf(pressed === 'run')}
          />
        </div>
      </div>
    </header>
  );
});

'use client';

import { useRef, useState } from 'react';

import { PencilIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';

type RenameInputProps = {
  value: string;
  label: string;
  /** `name` is null when nothing changed. `isFromKey` tells a key ended the edit, so the focus has to be put back. */
  onSettle: (name: string | null, isFromKey: boolean) => void;
  className?: string;
};

/** A name edited where it stands: Enter keeps it, Escape gives it up, leaving the field keeps it. */
export function RenameInput({
  value,
  label,
  onSettle,
  className,
}: RenameInputProps) {
  const [draft, setDraft] = useState(value);
  const isSettled = useRef(false);

  /** The field leaves the page when a key settles it, which blurs it: only the first of the two counts. */
  function settle(next: string, isFromKey: boolean) {
    if (isSettled.current) {
      return;
    }
    isSettled.current = true;
    const name = next.trim();
    const isNewName = name !== '' && name !== value;
    if (isNewName) {
      onSettle(name, isFromKey);
      return;
    }
    onSettle(null, isFromKey);
  }

  function settleFromKeys(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.nativeEvent.isComposing) {
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      settle(draft, true);
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      settle(value, true);
    }
  }

  return (
    <input
      autoFocus
      value={draft}
      aria-label={label}
      onChange={(event) => setDraft(event.target.value)}
      onFocus={(event) => event.currentTarget.select()}
      onKeyDown={settleFromKeys}
      onBlur={() => settle(draft, false)}
      className={cn(
        'bg-card text-foreground ring-ring/25 w-full min-w-0 rounded-sm px-1 text-base ring-[3px] outline-none select-text md:text-[13px]',
        className
      )}
    />
  );
}

type NameFieldProps = {
  value: string;
  /** The name of the field: "Workflow name". */
  label: string;
  /** What the button does, before the name: "Rename the workflow". */
  action: string;
  onRename: (name: string) => void;
  className?: string;
};

export function NameField({
  value,
  label,
  action,
  onRename,
  className,
}: NameFieldProps) {
  const [isEditing, setIsEditing] = useState(false);
  const buttonRef = useRef<HTMLButtonElement>(null);

  function settle(name: string | null, isFromKey: boolean) {
    setIsEditing(false);
    if (name !== null) {
      onRename(name);
    }
    if (isFromKey) {
      requestAnimationFrame(() => buttonRef.current?.focus());
    }
  }

  if (isEditing) {
    return (
      <RenameInput
        value={value}
        label={label}
        onSettle={settle}
        className={cn('h-6 font-medium', className)}
      />
    );
  }

  return (
    <button
      ref={buttonRef}
      type='button'
      aria-label={`${action}: ${value}`}
      onClick={() => setIsEditing(true)}
      className={cn(
        'group/name hover:bg-foreground/5 focus-visible:ring-ring/25 -mx-1 flex h-6 min-w-0 cursor-text items-center gap-1.5 rounded-sm px-1 text-start font-medium outline-none focus-visible:ring-[3px]',
        className
      )}
    >
      <span className='min-w-0 truncate'>{value}</span>
      <PencilIcon className='text-muted-foreground size-3 shrink-0 opacity-0 transition-opacity duration-150 group-hover/name:opacity-100 group-focus-visible/name:opacity-100' />
    </button>
  );
}

'use client';

import { memo, useId, useState } from 'react';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { PlusIcon, SearchIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { Input } from '@/registry/ndeko/ui/input';

import {
  GROUP_WORD,
  GROUPS,
  PALETTE,
  pressKeyOf,
  type PaletteEntry,
  type PaletteGroup,
} from './catalog';
import { modelOf } from './data';
import { LogicTile, MarkTile } from './node-tile';
import { toolOf } from './tools';

/** A row is positioned, so the word kept for screen readers inside it stays inside it. */
const ROW =
  'group/entry relative hover:bg-foreground/5 focus-visible:ring-ring/25 flex h-8 w-full min-w-0 cursor-pointer items-center gap-2 rounded-md px-1.5 text-start outline-none transition-[background-color,scale] duration-150 ease-(--ease-out-strong) focus-visible:ring-[3px] focus-visible:ring-inset active:scale-[0.97]';

function matchStartOf(text: string, query: string) {
  const needle = query.trim().toLowerCase();
  if (needle === '') {
    return -1;
  }
  const haystack = text.toLowerCase();
  return haystack.indexOf(needle);
}

function matches(entry: PaletteEntry, query: string) {
  const isSearching = query.trim() !== '';
  if (!isSearching) {
    return true;
  }
  return matchStartOf(entry.label, query) >= 0;
}

type MatchedTextProps = {
  text: string;
  query: string;
};

/** The part of a name that answers the search is marked, so it is clear why the entry stayed. */
function MatchedText({ text, query }: MatchedTextProps) {
  const start = matchStartOf(text, query);
  if (start < 0) {
    return text;
  }
  const needle = query.trim();
  const end = start + needle.length;

  return (
    <>
      {text.slice(0, start)}
      <mark className='bg-primary/15 text-foreground rounded-[3px]'>
        {text.slice(start, end)}
      </mark>
      {text.slice(end)}
    </>
  );
}

function EntryTile({ entry }: { entry: PaletteEntry }) {
  if (entry.group === 'models') {
    const model = modelOf(entry.modelId);
    return <BrandTile brand={model.brand} />;
  }
  if (entry.group === 'tools') {
    const tool = toolOf(entry.toolId);
    return <MarkTile mark={tool.mark} size='md' />;
  }
  return <LogicTile logic={entry.logic} size='md' />;
}

function hintOf(entry: PaletteEntry) {
  if (entry.group === 'logic') {
    return entry.hint;
  }
  return null;
}

type EntryRowProps = {
  entry: PaletteEntry;
  query: string;
  isPressed: boolean;
  onPick: (entry: PaletteEntry) => void;
};

function EntryRow({ entry, query, isPressed, onPick }: EntryRowProps) {
  const hint = hintOf(entry);

  return (
    <button
      type='button'
      onClick={() => onPick(entry)}
      className={cn(ROW, pressedQuietOf(isPressed))}
    >
      <EntryTile entry={entry} />
      <span className='shrink-0 text-[13px] font-medium'>
        <span className='sr-only'>Add </span>
        <MatchedText text={entry.label} query={query} />
      </span>
      <span className='text-muted-foreground min-w-0 flex-1 truncate text-xs'>
        {hint}
      </span>
      <PlusIcon className='text-muted-foreground size-3.5 shrink-0 opacity-0 transition-opacity duration-150 group-hover/entry:opacity-100 group-focus-visible/entry:opacity-100' />
    </button>
  );
}

type GroupListProps = {
  group: PaletteGroup;
  entries: PaletteEntry[];
  query: string;
  pressed: string | null;
  onPick: (entry: PaletteEntry) => void;
};

function GroupList({ group, entries, query, pressed, onPick }: GroupListProps) {
  const titleId = useId();

  return (
    <section aria-labelledby={titleId} className='flex flex-col'>
      <h3
        id={titleId}
