      >
        {GROUP_WORD[group]}
      </h3>
      <ul className='flex flex-col'>
        {entries.map((entry) => (
          <li key={entry.id}>
            <EntryRow
              entry={entry}
              query={query}
              isPressed={pressed === pressKeyOf(entry.id)}
              onPick={onPick}
            />
          </li>
        ))}
      </ul>
