'use client';

import {
  memo,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from 'react';

import { ARROW_OFFSET, GRID_CELL } from './canvas-frame';
import { EdgeLayer } from './edges';
import { outputLabelsOf, placementOf, walkOf } from './flow';
import { FlowStep, type StepActions } from './flow-step';
import { InsertButton } from './insert-button';
import { boxOf, type Box, type FlowLayout, type InsertPoint } from './layout';
import type { Workflow } from './model';
import { liveIdOf, type Run } from './run';
import { sampleOf } from './samples';
import { useFocusLater } from './use-focus-later';
import type { Viewport } from './use-viewport';
import { MAX_ZOOM, MIN_ZOOM } from './viewport';

/** The dots are drawn once on a layer large enough for the smallest zoom, then only moved. */
const GRID_SPARE_PX = GRID_CELL * MAX_ZOOM * 2;

const GRID_SIZE = `calc((100% + ${GRID_SPARE_PX}px) / ${MIN_ZOOM})`;

const GRID_STYLE = {
  width: GRID_SIZE,
  height: GRID_SIZE,
  backgroundSize: `${GRID_CELL}px ${GRID_CELL}px`,
};

/**
 * The frame clips its plane without being a scroll container. A step that takes the focus outside
 * a frame that hides its overflow would scroll it, and the plane would no longer sit where the view
 * says. The plane stays hidden until the frame has been measured, so it never shows at the wrong place.
 */
const FRAME =
  'focus-visible:ring-ring/25 relative min-h-0 min-w-0 flex-1 cursor-grab touch-none self-stretch overflow-clip outline-none select-none focus-visible:ring-[3px] focus-visible:ring-inset active:cursor-grabbing [&:not([data-ready])_[data-plane]]:invisible';

type HistoryKey = 'undo' | 'redo';

function historyKeyOf(event: React.KeyboardEvent): HistoryKey | null {
  const hasModifier = event.ctrlKey || event.metaKey;
  if (!hasModifier) {
    return null;
  }
  const key = event.key.toLowerCase();
  if (key === 'y') {
    return 'redo';
  }
  if (key !== 'z') {
    return null;
  }
  if (event.shiftKey) {
    return 'redo';
  }
  return 'undo';
}

/** A step that waits shows its card beside it: the two have to be in view together. */
function boxWithCard(box: Box, viewport: Viewport): Box {
  const frame = viewport.frameRef.current;
  const card = frame?.querySelector<HTMLElement>('[data-approval-card]');
  if (!frame || !card) {
    return box;
  }
  const view = viewport.store.get();
  const bounds = frame.getBoundingClientRect();
  const cardBox = card.getBoundingClientRect();
  const right = (cardBox.right - bounds.left - view.x) / view.zoom;
  const bottom = (cardBox.bottom - bounds.top - view.y) / view.zoom;
  const width = Math.max(box.width, right - box.x);
  const height = Math.max(box.height, bottom - box.y);
  return { ...box, width, height };
}

type CanvasProps = StepActions & {
  workflow: Workflow;
  layout: FlowLayout;
  viewport: Viewport;
  run: Run;
  selectedId: string | null;
  arrivedId: string | null;
  hasEdits: boolean;
  pressed: string | null;
  onRename: (id: string, name: string) => void;
  onUndo: () => void;
  onRedo: () => void;
};

const NO_INSERTS: InsertPoint[] = [];

/** The points where a step can be added, by the step the keyboard reaches them after. */
function insertsByStepOf(layout: FlowLayout) {
  const byStep = new Map<string | null, InsertPoint[]>();
  for (const insert of layout.inserts) {
    const held = byStep.get(insert.afterId) ?? [];
    byStep.set(insert.afterId, [...held, insert]);
  }
  return byStep;
}

/**
 * The plane of the flow in its frame. The frame is a group named after the workflow and the steps
 * are a list of buttons in the order of the flow, so the plan reads without the picture. It draws
 * again when what it shows changes, never while the settings of a step are typed.
 */
export const Canvas = memo(function Canvas({
  workflow,
  layout,
  viewport,
  run,
  selectedId,
  arrivedId,
  hasEdits,
  pressed,
  onSelect,
  onRemove,
  onDuplicate,
  onRename,
  onInsert,
  onDecide,
  onUndo,
  onRedo,
}: CanvasProps) {
  const hintId = useId();
  const { frameRef, planeRef, gridRef } = viewport;
  const { startPan, pan, endPan, cancelPan, panBy, reveal } = viewport;
  const { focusNode } = useFocusLater(frameRef);
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const latest = useRef({ layout, viewport });
  const lastToken = useRef(run.token);
  const placedSteps = useMemo(() => walkOf(workflow), [workflow]);
  const labels = useMemo(() => outputLabelsOf(workflow), [workflow]);
  const insertsByStep = useMemo(() => insertsByStepOf(layout), [layout]);
  const total = placedSteps.length;
  const sample = sampleOf(run.sampleId);
  const liveId = liveIdOf(run);
  const looseInserts = insertsByStep.get(null) ?? NO_INSERTS;
  const planeStyle = { width: layout.width, height: layout.height };

  useEffect(() => {
    latest.current = { layout, viewport };
  });

  /** A session that starts again goes back to the opening view. A new run is followed again. */
  useEffect(() => {
    const before = lastToken.current;
    lastToken.current = run.token;
    if (before === run.token) {
      return;
    }
    const current = latest.current;
    if (run.token === 0) {
      current.viewport.goHome();
      return;
    }
    current.viewport.startFollowing();
  }, [run.token]);

  useEffect(() => {
    if (liveId === null) {
      return;
    }
    const current = latest.current;
    const box = boxOf(current.layout, liveId);
    if (box) {
      const both = boxWithCard(box, current.viewport);
      current.viewport.follow(both);
    }
  }, [liveId]);

  useEffect(() => {
    if (arrivedId === null) {
      return;
    }
    const current = latest.current;
    const box = boxOf(current.layout, arrivedId);
    if (box) {
      current.viewport.reveal(box);
    }
  }, [arrivedId]);

  const revealStep = useCallback(
    (id: string) => {
      const box = boxOf(layout, id);
      if (box) {
        reveal(box);
      }
    },
    [layout, reveal]
  );

  const settleRename = useCallback(
    (id: string, name: string | null, isFromKey: boolean) => {
      setRenamingId(null);
      if (name !== null) {
        onRename(id, name);
      }
      if (isFromKey) {
        focusNode(id);
      }
    },
    [onRename, focusNode]
  );

  function playHistoryKey(key: HistoryKey) {
    if (key === 'undo') {
      onUndo();
      return;
    }
    onRedo();
  }

  function handleKeys(event: React.KeyboardEvent<HTMLDivElement>) {
    const isTyping = event.target instanceof HTMLInputElement;
    const historyKey = historyKeyOf(event);
    if (historyKey !== null && !isTyping) {
      event.preventDefault();
      playHistoryKey(historyKey);
      return;
    }
    const isOnCanvas = event.target === event.currentTarget;
    if (!isOnCanvas) {
      return;
    }
    const offset = ARROW_OFFSET[event.key];
    if (offset) {
      event.preventDefault();
      panBy(offset.x, offset.y);
      return;
    }
    const isRemoveKey = event.key === 'Delete' || event.key === 'Backspace';
    if (isRemoveKey && selectedId !== null) {
      event.preventDefault();
      onRemove(selectedId);
    }
  }

  return (
    <div
      ref={frameRef}
      role='group'
      tabIndex={0}
      data-canvas-frame
      aria-label={`${workflow.name}, workflow canvas`}
      aria-describedby={hintId}
      onKeyDown={handleKeys}
      onPointerDown={startPan}
      onPointerMove={pan}
      onPointerUp={endPan}
      onPointerCancel={cancelPan}
      className={FRAME}
    >
      <div
        ref={gridRef}
        aria-hidden='true'
        style={GRID_STYLE}
        className='pointer-events-none absolute top-0 left-0 origin-top-left bg-[radial-gradient(circle_at_1px_1px,color-mix(in_oklab,var(--foreground)_16%,transparent)_1px,transparent_1.5px)]'
      />
      <div
        ref={planeRef}
        data-plane
        style={planeStyle}
        className='absolute top-0 left-0 origin-top-left'
      >
        <EdgeLayer
          layout={layout}
          run={run}
          labels={labels}
          arrivedId={arrivedId}
          hasEdits={hasEdits}
        />
        <ol aria-label='Steps, in the order of the flow'>
          {placedSteps.map((placed) => {
            const stepId = placed.step.id;
            const box = boxOf(layout, stepId);
            if (!box) {
              return null;
            }
            return (
              <FlowStep
                key={stepId}
                placed={placed}
                total={total}
                box={box}
                inserts={insertsByStep.get(stepId) ?? NO_INSERTS}
                workflow={workflow}
                stepRun={run.steps[stepId]}
                sample={sample}
                isSelected={selectedId === stepId}
                isArrived={arrivedId === stepId}
                isRenaming={renamingId === stepId}
                pressed={pressed}
                onSelect={onSelect}
                onRemove={onRemove}
                onDuplicate={onDuplicate}
                onInsert={onInsert}
                onDecide={onDecide}
                onReveal={revealStep}
                onStartRename={setRenamingId}
                onSettleRename={settleRename}
              />
            );
          })}
        </ol>
        {looseInserts.map((insert) => (
          <InsertButton
            key={insert.id}
            x={insert.x}
            y={insert.y}
            placement={placementOf(workflow, insert.at)}
            onPick={(entry) => onInsert(insert.at, entry)}
          />
        ))}
      </div>
      {total === 0 && (
        <p className='text-muted-foreground pointer-events-none absolute inset-x-6 top-1/2 text-center text-[13px]'>
          This workflow has no step. Add one from the palette, or with the plus
          above
        </p>
      )}
      <p id={hintId} className='sr-only'>
        The arrow keys move the canvas. Tab walks the steps in the order of the
        flow, Enter opens the setup of a step, Delete removes it
      </p>
    </div>
  );
});

import type { Box, FlowLayout, Point } from './layout';
import {
  gridOffsetOf,
  homeOf,
  shiftInto,
  shownOf,
  type Insets,
  type Size,
  type View,
} from './viewport';

export const GRID_CELL = 20;

/** What is kept in view around a step the canvas pans to, so the edge that leaves it shows too. */
const REVEAL_MARGIN = 20;

const PAN_STEP = 56;

/** An arrow key moves the view that way, so what is on the canvas slides the other way. */
export const ARROW_OFFSET: Partial<Record<string, Point>> = {
  ArrowLeft: { x: PAN_STEP, y: 0 },
  ArrowRight: { x: -PAN_STEP, y: 0 },
  ArrowUp: { x: 0, y: PAN_STEP },
  ArrowDown: { x: 0, y: -PAN_STEP },
};

export const SAFE_MARGIN = 16;

/** A press on one of these is a press on the interface, not on the empty canvas behind it. */
const SOLID = 'button, a, input, textarea, select, label, [data-solid]';

export function flowSizeOf(layout: FlowLayout): Size {
  return { width: layout.width, height: layout.height };
}

/**
 * A layer drawn outside the frame (the menu of a step, the palette of a plus) still sends its
 * presses to the frame through React. Taken for the canvas, its item would lose its click to a pan.
 */
export function isOnBackground(frame: Element, target: EventTarget) {
  if (!(target instanceof Element)) {
    return false;
  }
  if (!frame.contains(target)) {
    return false;
  }
  return target.closest(SOLID) === null;
}

function overlayOf(frame: HTMLElement, name: string) {
  const panel = frame.parentElement;
  const overlay = panel?.querySelector<HTMLElement>(
    `[data-canvas-overlay="${name}"]`
  );
  return overlay?.getBoundingClientRect();
}

/** The tool bar and the row of buttons cover the frame: a view that shows the whole flow leaves them their room. */
export function insetsOf(frame: HTMLElement): Insets {
  const bounds = frame.getBoundingClientRect();
  const topBox = overlayOf(frame, 'top');
  const bottomBox = overlayOf(frame, 'bottom');
  const insets = { top: SAFE_MARGIN, bottom: SAFE_MARGIN };
  if (topBox && topBox.height > 0) {
    insets.top = topBox.bottom - bounds.top + SAFE_MARGIN;
  }
  if (bottomBox && bottomBox.height > 0) {
    insets.bottom = bounds.bottom - bottomBox.top + SAFE_MARGIN;
  }
  return insets;
}

/** Only what floats above or under a span counts: a card beside it hides nothing of it. */
export function clearSpanOf(frame: HTMLElement, left: number, right: number) {
  const bounds = frame.getBoundingClientRect();
  const panel = frame.parentElement;
  const overlays = panel?.querySelectorAll<HTMLElement>(
    '[data-canvas-overlay]'
  );
  const middle = bounds.height / 2;
  let top = SAFE_MARGIN;
  let bottom = bounds.height - SAFE_MARGIN;
  for (const overlay of overlays ?? []) {
    const box = overlay.getBoundingClientRect();
    const boxLeft = box.left - bounds.left;
    const boxRight = box.right - bounds.left;
    const boxTop = box.top - bounds.top;
    const boxBottom = box.bottom - bounds.top;
    const isEmpty = box.width === 0 || box.height === 0;
    const isBeside = boxRight < left || boxLeft > right;
    if (isEmpty || isBeside) {
      continue;
    }
    const boxMiddle = (boxTop + boxBottom) / 2;
    const isAbove = boxMiddle < middle;
    if (isAbove) {
      top = Math.max(top, boxBottom + SAFE_MARGIN);
    } else {
      bottom = Math.min(bottom, boxTop - SAFE_MARGIN);
    }
  }
  return { top, bottom };
}

/** How far the view moves so a step shows clear of what floats over the frame. Null when it already does. */
export function revealShiftOf(
  frame: HTMLElement,
  size: Size,
  view: View,
  box: Box
): Point | null {
  const shown = shownOf(view, {
    left: box.x - REVEAL_MARGIN,
    top: box.y - REVEAL_MARGIN,
    right: box.x + box.width + REVEAL_MARGIN,
    bottom: box.y + box.height + REVEAL_MARGIN,
  });
  const mostRight = size.width - SAFE_MARGIN;
  const shiftX = shiftInto(shown.left, shown.right, SAFE_MARGIN, mostRight);
  const movedLeft = shown.left + shiftX;
  const movedRight = shown.right + shiftX;
  const clear = clearSpanOf(frame, movedLeft, movedRight);
  const shiftY = shiftInto(shown.top, shown.bottom, clear.top, clear.bottom);
  const isInView = shiftX === 0 && shiftY === 0;
  if (isInView) {
    return null;
  }
  return { x: shiftX, y: shiftY };
}

export function writeView(
  view: View,
  plane: HTMLElement | null,
  grid: HTMLElement | null
) {
  const x = Math.round(view.x);
  const y = Math.round(view.y);
  if (plane) {
    const zoom = String(view.zoom);
    plane.style.transform = `translate(${x}px, ${y}px) scale(${zoom})`;
    plane.style.setProperty('--zoom', zoom);
  }
  if (grid) {
    const offset = gridOffsetOf({ x, y, zoom: view.zoom }, GRID_CELL);
    grid.style.transform = `translate(${offset.x}px, ${offset.y}px) scale(${view.zoom})`;
  }
}

export function homeViewOf(frame: HTMLElement, size: Size, layout: FlowLayout) {
  const flow = flowSizeOf(layout);
  const insets = insetsOf(frame);
  return homeOf(size, flow, layout.trunkX, insets);
}

'use client';

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
  type RefObject,
} from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

import {
  flowSizeOf,
  homeViewOf,
  insetsOf,
  isOnBackground,
  revealShiftOf,
  writeView,
} from './canvas-frame';
import type { Box, FlowLayout } from './layout';
import {
  clampedTo,
  createViewStore,
  fitOf,
  steppedZoom,
  zoomedAround,
  type Size,
  type View,
  type ViewStore,
} from './viewport';

/** A press that moved less than this was a click on the empty canvas, not a drag. */
const DRAG_SLACK_PX = 4;

const WHEEL_ZOOM_RATE = 0.0015;

type Drag = {
  pointerId: number;
  startX: number;
  startY: number;
  view: View;
  hasMoved: boolean;
};

function moveTo(store: ViewStore, view: View, shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    store.jump(view);
    return;
  }
  store.glide(view);
}

export type Viewport = {
  frameRef: RefObject<HTMLDivElement | null>;
  planeRef: RefObject<HTMLDivElement | null>;
  gridRef: RefObject<HTMLDivElement | null>;
  store: ViewStore;
  zoomBy: (direction: 1 | -1) => void;
  fit: () => void;
  goHome: () => void;
  panBy: (offsetX: number, offsetY: number) => void;
  show: (view: View) => void;
  reveal: (box: Box) => void;
  follow: (box: Box) => void;
  startFollowing: () => void;
  frameSizeOf: () => Size;
  startPan: (event: React.PointerEvent<HTMLDivElement>) => void;
  pan: (event: React.PointerEvent<HTMLDivElement>) => void;
  endPan: (event: React.PointerEvent<HTMLDivElement>) => void;
  cancelPan: () => void;
};

/**
 * Pan and zoom of the canvas: one transform on the plane, written straight to the element. A drag
 * on the empty canvas pans, Ctrl or Cmd with the wheel zooms round the pointer, and the view keeps
 * its opening position through a change of size for as long as nothing has moved it.
 * `onWheelZoom` hears the one gesture a demonstration cannot see by itself: a wheel is neither a
 * press nor a key.
 */
export function useViewport(
  layout: FlowLayout,
  onBackgroundPress: () => void,
  onWheelZoom: () => void
): Viewport {
  const [store] = useState(createViewStore);
  const frameRef = useRef<HTMLDivElement>(null);
  const planeRef = useRef<HTMLDivElement>(null);
  const gridRef = useRef<HTMLDivElement>(null);
  const frameSize = useRef<Size>({ width: 0, height: 0 });
  const latestLayout = useRef(layout);
  const isAtHome = useRef(true);
  const followsRun = useRef(true);
  const drag = useRef<Drag | null>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const { width, height, trunkX } = layout;

  useEffect(() => {
    latestLayout.current = layout;
  });

  useEffect(() => {
    function write() {
      const view = store.get();
      writeView(view, planeRef.current, gridRef.current);
    }
    write();
    const unsubscribe = store.subscribe(write);
    return () => {
      unsubscribe();
      store.stop();
    };
  }, [store]);

  useLayoutEffect(() => {
    const frame = frameRef.current;
    if (!frame) {
      return;
    }
    const observer = new ResizeObserver(([entry]) => {
      const box = entry.contentRect;
      const size = { width: box.width, height: box.height };
      frameSize.current = size;
      if (isAtHome.current) {
        const home = homeViewOf(frame, size, latestLayout.current);
        store.jump(home);
      } else {
        const flow = flowSizeOf(latestLayout.current);
        const kept = clampedTo(store.rest(), size, flow);
        store.jump(kept);
      }
      frame.dataset.ready = 'true';
    });
    observer.observe(frame);
    return () => observer.disconnect();
  }, [store]);

  useEffect(() => {
    const frame = frameRef.current;
    const size = frameSize.current;
    const isMeasured = size.width > 0;
    const canGoHome = isMeasured && isAtHome.current;
    if (!frame || !canGoHome) {
      return;
    }
    const home = homeViewOf(frame, size, latestLayout.current);
    moveTo(store, home, shouldReduceMotion);
  }, [store, width, height, trunkX, shouldReduceMotion]);

  useEffect(() => {
    const frame = frameRef.current;
    if (!frame) {
      return;
    }
    function zoomFromWheel(event: WheelEvent) {
      const isZoomGesture = event.ctrlKey || event.metaKey;
      if (!isZoomGesture || !frame) {
        return;
      }
      event.preventDefault();
      const bounds = frame.getBoundingClientRect();
      const anchor = {
        x: event.clientX - bounds.left,
        y: event.clientY - bounds.top,
      };
      const current = store.rest();
      const exponent = -event.deltaY * WHEEL_ZOOM_RATE;
      const zoom = current.zoom * Math.exp(exponent);
      const zoomed = zoomedAround(current, zoom, anchor);
      const flow = flowSizeOf(latestLayout.current);
      const kept = clampedTo(zoomed, frameSize.current, flow);
      isAtHome.current = false;
      followsRun.current = false;
      store.jump(kept);
      onWheelZoom();
    }
    frame.addEventListener('wheel', zoomFromWheel, { passive: false });
    return () => frame.removeEventListener('wheel', zoomFromWheel);
  }, [store, onWheelZoom]);

  /** Once a person moves the view it is theirs: it stops following the run and stays where they put it. */
  const takeOver = useCallback(() => {
    isAtHome.current = false;
    followsRun.current = false;
  }, []);

  const keptInFrame = useCallback(
    (view: View) => {
      const flow = flowSizeOf(layout);
      return clampedTo(view, frameSize.current, flow);
    },
    [layout]
  );

  const zoomBy = useCallback(
    (direction: 1 | -1) => {
      const size = frameSize.current;
      const centre = { x: size.width / 2, y: size.height / 2 };
      const current = store.rest();
      const zoom = steppedZoom(current.zoom, direction);
      const zoomed = zoomedAround(current, zoom, centre);
      const kept = keptInFrame(zoomed);
      takeOver();
      moveTo(store, kept, shouldReduceMotion);
    },
    [store, keptInFrame, takeOver, shouldReduceMotion]
  );

  const fit = useCallback(() => {
    const frame = frameRef.current;
    if (!frame) {
      return;
    }
    const insets = insetsOf(frame);
    const flow = flowSizeOf(layout);
    const fitted = fitOf(frameSize.current, flow, insets);
    takeOver();
    moveTo(store, fitted, shouldReduceMotion);
  }, [store, layout, takeOver, shouldReduceMotion]);

  const goHome = useCallback(() => {
    const frame = frameRef.current;
    isAtHome.current = true;
    followsRun.current = true;
    if (!frame || frameSize.current.width === 0) {
      return;
    }
    const home = homeViewOf(frame, frameSize.current, layout);
    moveTo(store, home, shouldReduceMotion);
  }, [store, layout, shouldReduceMotion]);

  const show = useCallback(
    (view: View) => {
      const kept = keptInFrame(view);
      takeOver();
      store.jump(kept);
    },
    [store, keptInFrame, takeOver]
  );

  const panBy = useCallback(
    (offsetX: number, offsetY: number) => {
      const current = store.rest();
      const moved = {
        x: current.x + offsetX,
        y: current.y + offsetY,
        zoom: current.zoom,
      };
      show(moved);
    },
    [store, show]
  );

  const reveal = useCallback(
    (box: Box) => {
      const frame = frameRef.current;
      const size = frameSize.current;
      if (!frame || size.width === 0) {
        return;
      }
      const current = store.rest();
      const shift = revealShiftOf(frame, size, current, box);
      if (shift === null) {
        return;
      }
      const moved = {
        x: current.x + shift.x,
        y: current.y + shift.y,
        zoom: current.zoom,
      };
      const kept = keptInFrame(moved);
      isAtHome.current = false;
      moveTo(store, kept, shouldReduceMotion);
    },
    [store, keptInFrame, shouldReduceMotion]
  );

  const follow = useCallback(
    (box: Box) => {
      if (followsRun.current) {
        reveal(box);
      }
    },
    [reveal]
  );

  const startFollowing = useCallback(() => {
    followsRun.current = true;
  }, []);

  const frameSizeOf = useCallback(() => frameSize.current, []);

  const startPan = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      const isMainButton = event.button === 0;
      const isOnCanvas = isOnBackground(event.currentTarget, event.target);
      if (!isMainButton || !isOnCanvas) {
        return;
      }
      event.currentTarget.setPointerCapture(event.pointerId);
      drag.current = {
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        view: store.rest(),
        hasMoved: false,
      };
    },
    [store]
  );

  const pan = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      const current = drag.current;
      if (current?.pointerId !== event.pointerId) {
        return;
      }
      const offsetX = event.clientX - current.startX;
      const offsetY = event.clientY - current.startY;
      const distance = Math.hypot(offsetX, offsetY);
      const isStill = !current.hasMoved && distance < DRAG_SLACK_PX;
      if (isStill) {
        return;
      }
      current.hasMoved = true;
      show({
        x: current.view.x + offsetX,
        y: current.view.y + offsetY,
        zoom: current.view.zoom,
      });
    },
    [show]
  );

  const endPan = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      const current = drag.current;
      if (current?.pointerId !== event.pointerId) {
        return;
      }
      drag.current = null;
      if (!current.hasMoved) {
        onBackgroundPress();
      }
    },
    [onBackgroundPress]
  );

  const cancelPan = useCallback(() => {
    drag.current = null;
  }, []);

  /** One object for as long as the layout stays: the canvas, the tool bar and the mini map hold still while a step is typed into. */
  return useMemo(
    () => ({
      frameRef,
      planeRef,
      gridRef,
      store,
      zoomBy,
      fit,
      goHome,
      panBy,
      show,
      reveal,
      follow,
      startFollowing,
      frameSizeOf,
      startPan,
      pan,
      endPan,
      cancelPan,
    }),
    [
      store,
      zoomBy,
      fit,
      goHome,
      panBy,
      show,
      reveal,
      follow,
      startFollowing,
      frameSizeOf,
      startPan,
      pan,
      endPan,
      cancelPan,
    ]
  );
}

function serverZoomPercent() {
  return 100;
}

/** The zoom as a whole percentage. Only the text that shows it reads this, so a drag draws nothing else again. */
export function useZoomPercent(store: ViewStore) {
  function readPercent() {
    const view = store.rest();
    return Math.round(view.zoom * 100);
  }
  return useSyncExternalStore(store.subscribe, readPercent, serverZoomPercent);
}

import type { Point } from './layout';

/** Where the plane of the canvas stands in its frame: one translation and one scale. */
export type View = {
  x: number;
  y: number;
  zoom: number;
};

export type Size = {
  width: number;
  height: number;
};

export type Rect = {
  left: number;
  top: number;
  right: number;
  bottom: number;
};

/** The part of the frame that toolbars and cards cover at its top and at its bottom. */
export type Insets = {
  top: number;
  bottom: number;
};

export const MIN_ZOOM = 0.4;

export const MAX_ZOOM = 1.6;

const ZOOM_STEP = 0.1;

/** Under this size the names on the cards stop being readable, so a canvas never opens smaller. */
const HOME_MIN_ZOOM = 0.8;

/** What stays of the flow in the frame however far it is panned, so it cannot be lost. */
const KEPT_IN_FRAME = 72;

const GLIDE_MS = 320;

/** A step counts as a tenth already reached when the zoom sits this close to it. */
const STEP_SLACK = 0.001;

const REST_VIEW: View = { x: 0, y: 0, zoom: 1 };

function clampedZoom(zoom: number) {
  const capped = Math.min(MAX_ZOOM, zoom);
  return Math.max(MIN_ZOOM, capped);
}

/** The whole flow, centred in the free part of the frame, never larger than life. */
export function fitOf(frame: Size, flow: Size, insets: Insets): View {
  const freeHeight = frame.height - insets.top - insets.bottom;
  const zoomAcross = frame.width / flow.width;
  const zoomDown = freeHeight / flow.height;
  const fitting = Math.min(zoomAcross, zoomDown, 1);
  const zoom = clampedZoom(fitting);
  const spareWidth = frame.width - flow.width * zoom;
  const spareHeight = freeHeight - flow.height * zoom;
  const offsetDown = Math.max(0, spareHeight / 2);
  return { x: spareWidth / 2, y: insets.top + offsetDown, zoom };
}

/** What a canvas opens on: the whole flow when it stays readable, else the top of the trunk at a readable size. */
export function homeOf(
  frame: Size,
  flow: Size,
  trunkX: number,
  insets: Insets
): View {
  const fit = fitOf(frame, flow, insets);
  if (fit.zoom >= HOME_MIN_ZOOM) {
    return fit;
  }
  const middle = frame.width / 2;
  const x = middle - trunkX * HOME_MIN_ZOOM;
  return { x, y: insets.top, zoom: HOME_MIN_ZOOM };
}

/** A new zoom that keeps the point under `anchor` where it is. */
export function zoomedAround(view: View, zoom: number, anchor: Point): View {
  const next = clampedZoom(zoom);
  const ratio = next / view.zoom;
  const x = anchor.x - (anchor.x - view.x) * ratio;
  const y = anchor.y - (anchor.y - view.y) * ratio;
  return { x, y, zoom: next };
}

/** The next tenth above or under a zoom: 88% goes to 90% or to 80%. */
export function steppedZoom(zoom: number, direction: 1 | -1) {
  const tenths = zoom / ZOOM_STEP;
  if (direction === 1) {
    const reached = Math.floor(tenths + STEP_SLACK);
    const above = (reached + 1) * ZOOM_STEP;
    return clampedZoom(above);
  }
  const reached = Math.ceil(tenths - STEP_SLACK);
  const under = (reached - 1) * ZOOM_STEP;
  return clampedZoom(under);
}

function clampedBetween(value: number, least: number, most: number) {
  const capped = Math.min(most, value);
  return Math.max(least, capped);
}

export function clampedTo(view: View, frame: Size, flow: Size): View {
  const leastX = KEPT_IN_FRAME - flow.width * view.zoom;
  const leastY = KEPT_IN_FRAME - flow.height * view.zoom;
  const mostX = frame.width - KEPT_IN_FRAME;
  const mostY = frame.height - KEPT_IN_FRAME;
  const x = clampedBetween(view.x, leastX, mostX);
  const y = clampedBetween(view.y, leastY, mostY);
  return { x, y, zoom: view.zoom };
}

export function shownOf(view: View, box: Rect): Rect {
  return {
    left: view.x + box.left * view.zoom,
    top: view.y + box.top * view.zoom,
    right: view.x + box.right * view.zoom,
    bottom: view.y + box.bottom * view.zoom,
  };
}

/** How far to move along one axis so a span fits between two bounds. Its start wins when it cannot fit. */
export function shiftInto(
  start: number,
  end: number,
  least: number,
  most: number
) {
  if (start < least) {
    return least - start;
  }
  if (end > most) {
    return most - end;
  }
  return 0;
}

function positiveModulo(value: number, size: number) {
  const remainder = value % size;
  return (remainder + size) % size;
}

/**
 * The grid starts one tile before the frame and slides by less than a tile, so it never shows an
 * edge and its dots stay on the same points of the plane at every zoom.
 */
export function gridOffsetOf(view: View, cell: number) {
  const scaled = cell * view.zoom;
  const x = positiveModulo(view.x, scaled);
  const y = positiveModulo(view.y, scaled);
  return { x: x - scaled, y: y - scaled };
}

function easedOut(progress: number) {
  const rest = 1 - progress;
  return 1 - rest * rest * rest * rest;
}

function between(from: number, to: number, share: number) {
  return from + (to - from) * share;
}

export type ViewStore = {
  /** Where the plane stands now, in the middle of a glide included. */
  get: () => View;
  /** Where it will rest: the end of the glide, or where it stands. */
  rest: () => View;
  jump: (view: View) => void;
  glide: (view: View) => void;
  subscribe: (listener: () => void) => () => void;
  stop: () => void;
};

/**
 * The view lives outside React: it changes on every frame of a drag or a glide, and only the
 * elements it moves are written to. A frame is asked for while a glide lasts, never at rest.
 */
export function createViewStore(): ViewStore {
  const listeners = new Set<() => void>();
  let view = REST_VIEW;
  let target = REST_VIEW;
  let origin = REST_VIEW;
  let startedAt = 0;
  let frame = 0;

  function notify() {
    for (const listener of listeners) {
      listener();
    }
  }

  function stop() {
    cancelAnimationFrame(frame);
    frame = 0;
  }

  function tick(now: number) {
    const elapsed = now - startedAt;
    const progress = Math.min(1, elapsed / GLIDE_MS);
    const share = easedOut(progress);
    view = {
      x: between(origin.x, target.x, share),
      y: between(origin.y, target.y, share),
      zoom: between(origin.zoom, target.zoom, share),
    };
    notify();
    if (progress >= 1) {
      frame = 0;
      return;
    }
    frame = requestAnimationFrame(tick);
  }

  return {
    get: () => view,
    rest: () => target,
    jump(next) {
      stop();
      view = next;
      target = next;
      notify();
    },
    glide(next) {
      stop();
      origin = view;
      target = next;
      startedAt = performance.now();
      frame = requestAnimationFrame(tick);
      notify();
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    stop,
  };
}

import { edgeIdOf } from './flow';
import type {
  BranchOutput,
  BranchStep,
  InsertAt,
  Step,
  Workflow,
} from './model';

export const NODE_WIDTH = 208;

export const NODE_HEIGHT = 52;

const COLUMN_GAP = 24;

const ROW_GAP = 36;

const PADDING = 32;

/** Under a branch: the line that carries its outputs sideways, then down each column a label, an insert point and the first step. */
const FORK_BUS = 14;

const FORK_LABEL = 18;

const FORK_INSERT = 42;

const FORK_STEP = 56;

/** Where outputs join: the line that brings them back under the branch, then the step they join at. */
const JOIN_BUS = 30;

const JOIN_STEP = 30;

const INSERT_DROP = 15;

const TAIL_DROP = 28;

const ELBOW_RADIUS = 8;

export type Point = {
  x: number;
  y: number;
};

export type Box = {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
};

export type FlowEdge = {
  id: string;
  fromId: string;
  /** Null for the edge that ends the flow. */
  toId: string | null;
  outputId: string | null;
  /** Where the label of an output sits. Its text is not here: a layout reads only the structure of the flow. */
  labelAt: Point | null;
  /** The corners the path turns at, from its first point to its last: what travels along the edge follows them. */
  points: Point[];
  path: string;
};

export type InsertPoint = {
  id: string;
  at: InsertAt;
  x: number;
  y: number;
  /** The step read just before this point in the order of the flow: the keyboard reaches the point right after it. */
  afterId: string | null;
};

export type FlowLayout = {
  width: number;
  height: number;
  trunkX: number;
  /** In the order of the flow, the outputs of a branch left to right. */
  boxes: Box[];
  edges: FlowEdge[];
  inserts: InsertPoint[];
};

/** An edge that has left its step and has not reached the next one yet. */
type OpenEnd = {
  fromId: string;
  outputId: string | null;
  labelAt: Point | null;
  points: Point[];
};

type Draft = {
  boxes: Box[];
  edges: FlowEdge[];
  inserts: InsertPoint[];
  lastId: string | null;
};

type Placement = {
  ends: OpenEnd[];
  bottom: number;
};

/** A list is as wide as its widest step, and a branch as wide as its outputs side by side. */
function widthOfList(steps: Step[]): number {
  let width = NODE_WIDTH;
  for (const step of steps) {
    const stepWidth = widthOfStep(step);
    width = Math.max(width, stepWidth);
  }
  return width;
}

function widthOfStep(step: Step): number {
  if (step.kind !== 'branch') {
    return NODE_WIDTH;
  }
  let width = 0;
  for (const output of step.outputs) {
    width += widthOfList(output.steps);
  }
  const gaps = step.outputs.length - 1;
  return width + gaps * COLUMN_GAP;
}

function distanceOf(from: Point, to: Point) {
  const offsetX = to.x - from.x;
  const offsetY = to.y - from.y;
  return Math.hypot(offsetX, offsetY);
}

function towards(from: Point, to: Point, distance: number): Point {
  const length = distanceOf(from, to);
  if (length === 0) {
    return from;
  }
  const share = distance / length;
  const offsetX = (to.x - from.x) * share;
  const offsetY = (to.y - from.y) * share;
  return { x: from.x + offsetX, y: from.y + offsetY };
}

/** An elbow: the line stops short of the corner and a curve takes the turn, never over more than half a side. */
function elbowOf(before: Point, corner: Point, after: Point) {
  const sideIn = distanceOf(before, corner);
  const sideOut = distanceOf(corner, after);
  const shortSide = Math.min(sideIn, sideOut);
  const radius = Math.min(ELBOW_RADIUS, shortSide / 2);
  const start = towards(corner, before, radius);
  const end = towards(corner, after, radius);
  return `L ${start.x} ${start.y} Q ${corner.x} ${corner.y} ${end.x} ${end.y}`;
}

function pathOf(points: Point[]) {
  const first = points[0];
  const last = points[points.length - 1];
  const parts = [`M ${first.x} ${first.y}`];
  for (let index = 1; index < points.length - 1; index += 1) {
    const before = points[index - 1];
    const corner = points[index];
    const after = points[index + 1];
    const elbow = elbowOf(before, corner, after);
    parts.push(elbow);
  }
  parts.push(`L ${last.x} ${last.y}`);
  return parts.join(' ');
}

/** Straight down when the target sits under the end, else down to a line just above the target and across to it. */
function routeTo(end: OpenEnd, target: Point): Point[] {
  const last = end.points[end.points.length - 1];
  if (last.x === target.x) {
    return [...end.points, target];
  }
  const busY = target.y - JOIN_STEP;
  const down = { x: last.x, y: busY };
  const across = { x: target.x, y: busY };
  return [...end.points, down, across, target];
}

function closeEnd(
  draft: Draft,
  end: OpenEnd,
  toId: string | null,
  target: Point
) {
  const points = routeTo(end, target);
  draft.edges.push({
    id: edgeIdOf(end.fromId, end.outputId),
    fromId: end.fromId,
    toId,
    outputId: end.outputId,
    labelAt: end.labelAt,
    points,
    path: pathOf(points),
  });
}

function insertIdOf(at: InsertAt) {
  if (at.at === 'after') {
    return `after:${at.stepId}`;
  }
  if (at.at === 'first') {
    return `first:${at.branchId}:${at.outputId}`;
  }
  return 'end';
}

function addInsert(draft: Draft, at: InsertAt, point: Point) {
  draft.inserts.push({
    id: insertIdOf(at),
    at,
    x: point.x,
    y: point.y,
    afterId: draft.lastId,
  });
}

/** The edge of an output leaves the branch, runs along the line under it and stops above its own column. */
function forkEndOf(
  branch: BranchStep,
  output: BranchOutput,
  from: Point,
  columnX: number
): OpenEnd {
  const busY = from.y + FORK_BUS;
  const points = [from, { x: from.x, y: busY }];
  if (columnX !== from.x) {
    points.push({ x: columnX, y: busY });
  }
  return {
    fromId: branch.id,
    outputId: output.id,
    labelAt: { x: columnX, y: busY + FORK_LABEL },
    points,
  };
}

function placeBranch(draft: Draft, branch: BranchStep, from: Point): Placement {
  const busY = from.y + FORK_BUS;
  const firstTop = busY + FORK_STEP;
  const ends: OpenEnd[] = [];
  const total = widthOfStep(branch);
  let left = from.x - total / 2;
  let bottom = firstTop;
  for (const output of branch.outputs) {
    const width = widthOfList(output.steps);
    const columnX = left + width / 2;
    const end = forkEndOf(branch, output, from, columnX);
    const first: InsertAt = {
      at: 'first',
      branchId: branch.id,
      outputId: output.id,
    };
    addInsert(draft, first, { x: columnX, y: busY + FORK_INSERT });
    const placed = placeList(draft, output.steps, columnX, firstTop, [end]);
    ends.push(...placed.ends);
    bottom = Math.max(bottom, placed.bottom);
    left += width + COLUMN_GAP;
  }
  return { ends, bottom };
}

/**
 * Places a list of steps down one column. `incoming` are the edges that reach its first step. It
 * returns the edges that leave it, for the step that comes next in the list above.
 */
function placeList(
  draft: Draft,
  steps: Step[],
  centerX: number,
  top: number,
  incoming: OpenEnd[],
  isTrunk = false
): Placement {
  let ends = incoming;
  let cursor = top;
  let bottom = top;
  let previous: Step | null = null;
  for (const [index, step] of steps.entries()) {
    const target = { x: centerX, y: cursor };
    if (previous?.kind === 'branch') {
      const join: InsertAt = { at: 'after', stepId: previous.id };
      addInsert(draft, join, { x: centerX, y: cursor - INSERT_DROP });
    }
    for (const end of ends) {
      closeEnd(draft, end, step.id, target);
    }
    draft.boxes.push({
      id: step.id,
      x: centerX - NODE_WIDTH / 2,
      y: cursor,
      width: NODE_WIDTH,
      height: NODE_HEIGHT,
    });
    draft.lastId = step.id;
    const stepBottom = cursor + NODE_HEIGHT;
    const exit = { x: centerX, y: stepBottom };
    if (step.kind === 'branch') {
      const fork = placeBranch(draft, step, exit);
      ends = fork.ends;
      bottom = fork.bottom;
      cursor = fork.bottom + JOIN_BUS + JOIN_STEP;
    } else {
      const isLast = index === steps.length - 1;
      addOwnInsert(draft, step, exit, isLast, isTrunk);
      ends = [openEndOf(step, exit)];
      bottom = stepBottom;
      cursor = stepBottom + ROW_GAP;
    }
    previous = step;
  }
  return { ends, bottom };
}

function openEndOf(step: Step, exit: Point): OpenEnd {
  return {
    fromId: step.id,
    outputId: null,
    labelAt: null,
    points: [exit],
  };
}

/**
 * Between two steps the point sits halfway. Under the last step of an output it sits close to the
 * step, since the line then turns towards the join. The last step of the trunk has none: the point
 * that ends the flow stands for it.
 */
function addOwnInsert(
  draft: Draft,
  step: Step,
  exit: Point,
  isLast: boolean,
  isTrunk: boolean
) {
  const after: InsertAt = { at: 'after', stepId: step.id };
  if (!isLast) {
    addInsert(draft, after, { x: exit.x, y: exit.y + ROW_GAP / 2 });
    return;
  }
  if (!isTrunk) {
    addInsert(draft, after, { x: exit.x, y: exit.y + INSERT_DROP });
  }
}

function tailYOf(bottom: number, last: Step | undefined) {
  if (!last) {
    return bottom + INSERT_DROP;
  }
  if (last.kind === 'branch') {
    return bottom + JOIN_BUS + JOIN_STEP;
  }
  return bottom + TAIL_DROP;
}

/** The whole canvas from the data and nothing else: where each step sits, how each edge runs, where a step can be added. */
export function layoutOf(workflow: Workflow): FlowLayout {
  const draft: Draft = { boxes: [], edges: [], inserts: [], lastId: null };
  const inner = widthOfList(workflow.steps);
  const width = inner + PADDING * 2;
  const trunkX = width / 2;
  const placed = placeList(draft, workflow.steps, trunkX, PADDING, [], true);
  const last = workflow.steps.at(-1);
  const tail = { x: trunkX, y: tailYOf(placed.bottom, last) };
  for (const end of placed.ends) {
    closeEnd(draft, end, null, tail);
  }
  addInsert(draft, { at: 'end' }, tail);
  return {
    width,
    height: tail.y + PADDING,
    trunkX,
    boxes: draft.boxes,
    edges: draft.edges,
    inserts: draft.inserts,
  };
}

export function boxOf(layout: FlowLayout, id: string) {
  return layout.boxes.find((box) => box.id === id);
}

export function lengthOf(points: Point[]) {
  let length = 0;
  for (let index = 1; index < points.length; index += 1) {
    const from = points[index - 1];
    const to = points[index];
    length += distanceOf(from, to);
  }
  return length;
}

'use client';

import { memo } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

import { ApprovalCard } from './approval-card';
import type { PaletteEntry } from './catalog';
import { nodePressKeyOf, placementOf, type Placed } from './flow';
import { InsertButton } from './insert-button';
import { NODE_HEIGHT, NODE_WIDTH, type Box, type InsertPoint } from './layout';
import type { InsertAt, Step, Workflow } from './model';
import { NodeCard } from './node-card';
import type { Decision, StepRun } from './run';
import type { Sample } from './samples';

function askingOf(step: Step, isWaiting: boolean) {
  if (step.kind !== 'approval' || !isWaiting) {
    return null;
  }
  return step;
}

/** The card of a step and what hangs from it take their size from the layout, so the two never disagree. */
type StepStyle = React.CSSProperties & {
  '--step-width': string;
  '--step-height': string;
};

/** The step that waits sits above the ones under it, so its card covers them and not the other way round. */
function layerOf(isWaiting: boolean) {
  if (isWaiting) {
    return 'z-10';
  }
  return 'z-0';
}

export type StepActions = {
  onSelect: (id: string, isFromKeyboard: boolean) => void;
  onRemove: (id: string) => void;
  onDuplicate: (id: string) => void;
  onInsert: (at: InsertAt, entry: PaletteEntry) => void;
  onDecide: (decision: Decision) => void;
};

type FlowStepProps = StepActions & {
  placed: Placed;
  total: number;
  box: Box;
  inserts: InsertPoint[];
  workflow: Workflow;
  /** The mark of this step in the run: a beat that touches another step leaves this one as it is. */
  stepRun: StepRun | undefined;
  sample: Sample;
  isSelected: boolean;
  isArrived: boolean;
  isRenaming: boolean;
  pressed: string | null;
  onReveal: (id: string) => void;
  onStartRename: (id: string) => void;
  onSettleRename: (id: string, name: string | null, isFromKey: boolean) => void;
};

/**
 * One step of the list, with what the keyboard reaches right after it: its card when it waits for
 * a person, then the points where a step can be added before the next one.
 */
export const FlowStep = memo(function FlowStep({
  placed,
  total,
  box,
  inserts,
  workflow,
  stepRun,
  sample,
  isSelected,
  isArrived,
  isRenaming,
  pressed,
  onSelect,
  onRemove,
  onDuplicate,
  onInsert,
  onDecide,
  onReveal,
  onStartRename,
  onSettleRename,
}: FlowStepProps) {
  const { step } = placed;
  const isWaiting = stepRun?.status === 'waiting';
  const asking = askingOf(step, isWaiting);
  const placeStyle: StepStyle = {
    translate: `${box.x}px ${box.y}px`,
    '--step-width': `${NODE_WIDTH}px`,
    '--step-height': `${NODE_HEIGHT}px`,
  };

  return (
    <li
      style={placeStyle}
      className={cn(
        'absolute top-0 left-0 transition-[translate] duration-300 ease-(--ease-out-strong)',
        layerOf(isWaiting)
      )}
    >
      <NodeCard
        step={step}
        position={placed.position}
        total={total}
        branchLabel={placed.branchLabel}
        stepRun={stepRun}
        isSelected={isSelected}
        isArrived={isArrived}
        isPressed={pressed === nodePressKeyOf(step.id)}
        isRenaming={isRenaming}
        onSelect={onSelect}
        onReveal={onReveal}
        onRemove={onRemove}
        onDuplicate={onDuplicate}
        onStartRename={onStartRename}
        onSettleRename={onSettleRename}
      />
      {asking && (
        <ApprovalCard
          step={asking}
          sample={sample}
          workflowName={workflow.name}
          pressed={pressed}
          onDecide={onDecide}
        />
      )}
      {inserts.map((insert) => (
        <InsertButton
          key={insert.id}
          x={insert.x - box.x}
          y={insert.y - box.y}
          placement={placementOf(workflow, insert.at)}
          onPick={(entry) => onInsert(insert.at, entry)}
        />
      ))}
    </li>
  );
});

'use client';

import { memo, useRef } from 'react';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import {
  CopyPlusIcon,
  EllipsisIcon,
  PencilIcon,
  Trash2Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

import { KIND_WORD, type Step } from './model';
import { RenameInput } from './name-field';
import { StepTile } from './node-tile';
import type { StepRun, StepStatus } from './run';
import { StateMark, stateWordsOf } from './state-mark';

const CARD =
  'bg-card relative flex h-(--step-height) w-(--step-width) items-center rounded-xl transition-[translate,box-shadow,opacity,scale,background-color] duration-200 ease-(--ease-out-strong)';

/** A step that was just added grows into its place. The others were there already and do not play it. */
const ARRIVAL = 'starting:scale-95 starting:opacity-0';

const RESTING = 'shadow-[0_1px_2px_rgb(0_0_0/0.04)]';

/** A step at work lifts by a pixel, under a hairline of the primary colour. */
const LIFTED = '-translate-y-px shadow-[0_4px_10px_-3px_rgb(0_0_0/0.14)]';

/** A note of the run takes the place of the kind with a fade. The kind itself is simply there when the page loads. */
const NOTE_FADE = 'transition-opacity duration-300 starting:opacity-0';

function isAtWork(status: StepStatus | undefined) {
  return status === 'running' || status === 'retrying';
}

function ringOf(isSelected: boolean, status: StepStatus | undefined) {
  if (isSelected) {
    return 'ring-primary/60 ring-2';
  }
  if (isAtWork(status)) {
    return 'hairline-ring ring-primary';
  }
  if (status === 'failed') {
    return 'hairline-ring ring-destructive/50';
  }
  if (status === 'waiting') {
    return 'hairline-ring ring-warning/70';
  }
  return 'hairline-ring ring-border';
}

function liftOf(status: StepStatus | undefined) {
  if (isAtWork(status)) {
    return LIFTED;
  }
  return RESTING;
}

function noteFadeOf(hasNote: boolean) {
  if (hasNote) {
    return NOTE_FADE;
  }
  return undefined;
}

function standingOf(status: StepStatus | undefined) {
  if (status === 'skipped') {
    return 'opacity-50';
  }
  return 'opacity-100';
}

function arrivalOf(isArrived: boolean) {
  if (isArrived) {
    return ARRIVAL;
  }
  return undefined;
}

function overlineToneOf(status: StepStatus | undefined) {
  if (status === 'failed') {
    return 'text-destructive-ink';
  }
  if (status === 'waiting') {
    return 'text-warning-foreground';
  }
  return 'text-muted-foreground';
}

/** "Tool: Find the order, step 4 of 10, Refund branch, done in 0.7s". */
function nameOf(
  step: Step,
  position: number,
  total: number,
  branchLabel: string | null,
  stepRun: StepRun | undefined
) {
  const parts = [
    `${KIND_WORD[step.kind]}: ${step.name}`,
    `step ${position} of ${total}`,
  ];
  if (branchLabel !== null) {
    parts.push(`${branchLabel} branch`);
  }
  const state = stateWordsOf(stepRun);
  parts.push(state);
  return parts.join(', ');
}

type NodeMenuProps = {
  name: string;
  onRename: () => void;
  onDuplicate: () => void;
  onRemove: () => void;
};

function NodeMenu({ name, onRename, onDuplicate, onRemove }: NodeMenuProps) {
  const hasActed = useRef(false);

  function choose(action: () => void) {
    hasActed.current = true;
    action();
  }

  /** After an action the focus goes where the action leads: the field, the copy, the step before. Closing without one gives it back to the button. */
  function returnsFocus() {
    const wasActed = hasActed.current;
    hasActed.current = false;
    return !wasActed;
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            type='button'
            variant='ghost'
            size='icon-sm'
            aria-label={`Actions for ${name}`}
            className='text-muted-foreground absolute end-1.5 bottom-1.5 size-6'
          />
        }
      >
        <EllipsisIcon className='size-3.5' />
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align='start'
        className='w-44'
        finalFocus={returnsFocus}
      >
        <DropdownMenuItem onClick={() => choose(onRename)}>
          <PencilIcon />
          Rename
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => choose(onDuplicate)}>
          <CopyPlusIcon />
          Duplicate
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem
          variant='destructive'
          onClick={() => choose(onRemove)}
        >
          <Trash2Icon />
          Delete
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

type NodeCardProps = {
  step: Step;
  position: number;
  total: number;
  branchLabel: string | null;
  stepRun: StepRun | undefined;
  isSelected: boolean;
  isArrived: boolean;
  isPressed: boolean;
  isRenaming: boolean;
  onSelect: (id: string, isFromKeyboard: boolean) => void;
  onReveal: (id: string) => void;
  onRemove: (id: string) => void;
  onDuplicate: (id: string) => void;
  onStartRename: (id: string) => void;
  onSettleRename: (id: string, name: string | null, isFromKey: boolean) => void;
};

export const NodeCard = memo(function NodeCard({
  step,
  position,
  total,
  branchLabel,
  stepRun,
  isSelected,
  isArrived,
  isPressed,
  isRenaming,
  onSelect,
  onReveal,
  onRemove,
  onDuplicate,
  onStartRename,
  onSettleRename,
}: NodeCardProps) {
  const status = stepRun?.status;
  const note = stepRun?.note ?? null;
  const overline = note ?? KIND_WORD[step.kind];
  const name = nameOf(step, position, total, branchLabel, stepRun);

  /** A click from the keyboard carries no press of a pointer: that is how Enter and Space are told apart from a tap. */
  function select(event: React.MouseEvent<HTMLButtonElement>) {
    const isFromKeyboard = event.detail === 0;
    event.currentTarget.focus();
    onSelect(step.id, isFromKeyboard);
  }

  /** A step reached with the keyboard may sit outside the frame: the canvas brings it into view. A press of a pointer never moves it. */
  function revealFromKeys(event: React.FocusEvent<HTMLButtonElement>) {
    if (event.currentTarget.matches(':focus-visible')) {
      onReveal(step.id);
    }
  }

  function handleKeys(event: React.KeyboardEvent<HTMLButtonElement>) {
    const isRemoveKey = event.key === 'Delete' || event.key === 'Backspace';
    if (isRemoveKey) {
      event.preventDefault();
      onRemove(step.id);
      return;
    }
    if (event.key === 'F2') {
      event.preventDefault();
      onStartRename(step.id);
    }
  }

  if (isRenaming) {
    return (
      <div
        data-solid
        className={cn(CARD, 'ring-primary/60 gap-2.5 px-2.5 ring-2')}
      >
        <StepTile step={step} />
        <span className='flex min-w-0 flex-1 flex-col'>
          <span className='text-muted-foreground text-[11px] leading-4'>
            {KIND_WORD[step.kind]}
          </span>
          <RenameInput
            value={step.name}
            label={`Name of the step ${step.name}`}
            onSettle={(next, isFromKey) =>
              onSettleRename(step.id, next, isFromKey)
            }
            className='-mx-1 h-5 font-medium'
          />
        </span>
      </div>
    );
  }

  return (
    <div
      data-solid
      className={cn(
        CARD,
        ringOf(isSelected, status),
        liftOf(status),
        standingOf(status),
        arrivalOf(isArrived),
        pressedQuietOf(isPressed)
      )}
    >
      <button
        type='button'
        data-node={step.id}
        aria-label={name}
        aria-pressed={isSelected}
        aria-keyshortcuts='F2 Delete'
        onClick={select}
        onFocus={revealFromKeys}
        onKeyDown={handleKeys}
        className='focus-visible:ring-ring focus-visible:ring-offset-background flex h-full min-w-0 flex-1 cursor-pointer items-center gap-2.5 rounded-xl px-2.5 text-start outline-none focus-visible:ring-2 focus-visible:ring-offset-2'
      >
        <StepTile step={step} />
        <span className='flex min-w-0 flex-1 flex-col'>
          <span className='flex h-4 items-center gap-1.5'>
            <span
              key={overline}
              className={cn(
                'min-w-0 flex-1 truncate text-[11px] leading-4',
                overlineToneOf(status),
                noteFadeOf(note !== null)
              )}
            >
              {overline}
            </span>
            <StateMark stepRun={stepRun} />
          </span>
          <span className='truncate pe-6 text-[13px] leading-5 font-medium'>
            {step.name}
          </span>
        </span>
      </button>
      <NodeMenu
        name={step.name}
        onRename={() => onStartRename(step.id)}
        onDuplicate={() => onDuplicate(step.id)}
        onRemove={() => onRemove(step.id)}
      />
    </div>
  );
});

import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import {
  GitBranchIcon,
  HourglassIcon,
  RepeatIcon,
  ShieldCheckIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';

import type { LogicKind } from './catalog';
import { isProductStep, type Step } from './model';
import { toolOf, type ToolMark } from './tools';

export type TileSize = 'md' | 'lg';

const KEYCAP_CLASS: Record<TileSize, string> = {
  md: 'size-5 rounded-[5px]',
  lg: 'size-7 rounded-md',
};

const GLYPH_CLASS: Record<TileSize, string> = {
  md: 'size-3',
  lg: 'size-4',
};

const LOGIC_ICON: Record<LogicKind, Icon> = {
  branch: GitBranchIcon,
  approval: ShieldCheckIcon,
  wait: HourglassIcon,
  loop: RepeatIcon,
};

type LogicTileProps = {
  logic: LogicKind;
  size?: TileSize;
};

/** A step of logic belongs to no product, so it wears a key cap with the icon of what it does. */
export function LogicTile({ logic, size = 'lg' }: LogicTileProps) {
  const Glyph = LOGIC_ICON[logic];

  return (
    <span
      aria-hidden='true'
      className={cn(
        'keycap-3d text-muted-foreground inline-flex shrink-0 items-center justify-center',
        KEYCAP_CLASS[size]
      )}
    >
      <Glyph className={GLYPH_CLASS[size]} />
    </span>
  );
}

type MarkTileProps = {
  mark: ToolMark;
  size?: TileSize;
};

export function MarkTile({ mark, size = 'lg' }: MarkTileProps) {
  if (mark.kind === 'brand') {
    return <BrandTile brand={mark.brand} size={size} />;
  }
  return <CompanyMark seed={mark.seed} size={size} />;
}

type StepTileProps = {
  step: Step;
  size?: TileSize;
};

/** An agent wears a picture in its series colour, a step of a product the mark of the product. */
export function StepTile({ step, size = 'lg' }: StepTileProps) {
  if (step.kind === 'agent') {
    const color = seriesColorOf(step.series);
    return <MeshTile seed={step.seed} color={color} size={size} />;
  }
  if (isProductStep(step)) {
    const tool = toolOf(step.tool.toolId);
    return <MarkTile mark={tool.mark} size={size} />;
  }
  return <LogicTile logic={step.kind} size={size} />;
}

'use client';

import { motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { formatDuration } from '@/registry/ndeko/lib/agent-run';
import {
  CircleCheckIcon,
  CircleDashedIcon,
  CircleXIcon,
  HandIcon,
  LoaderCircleIcon,
} from '@/registry/ndeko/lib/icons';
import { EASE_IN_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { Swap } from '@/registry/ndeko/ui/chat-motion';

import type { StepRun, StepStatus } from './run';

const STATUS_WORD: Record<StepStatus, string> = {
  running: 'running',
  retrying: 'trying again',
  failed: 'failed',
  waiting: 'waiting for you',
  done: 'done',
  denied: 'denied by you',
  skipped: 'skipped',
};

const ONE_TURN = { rotate: 360 };

const TURN_TIMING = { duration: 0.8, ease: EASE_IN_OUT_STRONG };

/** The mark turns once when a step starts, then holds still: nothing keeps spinning while a step only waits to end. */
function TurningMark() {
  const shouldReduceMotion = usePrefersReducedMotion();

  if (shouldReduceMotion) {
    return <LoaderCircleIcon className='text-primary-ink size-4' />;
  }
  return (
    <motion.span
      initial={{ rotate: 0 }}
      animate={ONE_TURN}
      transition={TURN_TIMING}
      className='inline-flex'
    >
      <LoaderCircleIcon className='text-primary-ink size-4' />
    </motion.span>
  );
}

function StatusGlyph({ status }: { status: StepStatus }) {
  const isAtWork = status === 'running' || status === 'retrying';
  if (isAtWork) {
    return <TurningMark />;
  }
  if (status === 'failed') {
    return <CircleXIcon className='text-destructive-ink size-4' />;
  }
  if (status === 'waiting') {
    return <HandIcon className='text-warning-foreground size-4' />;
  }
  if (status === 'done') {
    return <CircleCheckIcon className='text-success-foreground size-4' />;
  }
  if (status === 'denied') {
    return <CircleXIcon className='text-muted-foreground size-4' />;
  }
  return <CircleDashedIcon className='text-muted-foreground size-4' />;
}

/** A step that is done shows how long it took, one that was left out says so. */
function captionOf(stepRun: StepRun) {
  if (stepRun.status === 'skipped') {
    return 'Skipped';
  }
  const hasDuration = stepRun.status === 'done' && stepRun.ms > 0;
  if (hasDuration) {
    return formatDuration(stepRun.ms);
  }
  return null;
}

type StateMarkProps = {
  stepRun: StepRun | undefined;
};

/** Drawn for the eye only: the button of the step says the same state in words. */
export function StateMark({ stepRun }: StateMarkProps) {
  if (!stepRun) {
    return null;
  }
  const caption = captionOf(stepRun);

  return (
    <span aria-hidden='true' className='flex shrink-0 items-center gap-1'>
      {caption && (
        <span className='text-muted-foreground text-[11px] leading-4 tabular-nums'>
          {caption}
        </span>
      )}
      <Swap swapKey={stepRun.status} className='size-4'>
        <StatusGlyph status={stepRun.status} />
      </Swap>
    </span>
  );
}

function timedWordOf(word: string, ms: number) {
  if (ms <= 0) {
    return word;
  }
  const duration = formatDuration(ms);
  return `${word} in ${duration}`;
}

export function stateWordsOf(stepRun: StepRun | undefined) {
  if (!stepRun) {
    return 'not run yet';
  }
  const word = STATUS_WORD[stepRun.status];
  if (stepRun.status === 'failed') {
    const reason = stepRun.note ?? 'no answer';
    return `${word}: ${reason}`;
  }
  if (stepRun.status !== 'done') {
    return word;
  }
  const timed = timedWordOf(word, stepRun.ms);
  if (stepRun.note) {
    return `${timed}. ${stepRun.note}`;
  }
  return timed;
}

'use client';

import { motion, type Transition } from 'motion/react';
import { memo, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

import { lengthOf, type FlowEdge, type FlowLayout, type Point } from './layout';
import { TRAVEL_MS, type Run } from './run';

type EdgeTone = 'idle' | 'taken' | 'leftOut';

const TONE_CLASS: Record<EdgeTone, string> = {
  idle: 'opacity-100',
  taken: 'opacity-100',
  leftOut: 'opacity-35',
};

/** The stroke shows from its first point to its last, once: the path is one dash that slides into place. */
const DRAWN =
  '[stroke-dasharray:1] [stroke-dashoffset:0] transition-[stroke-dashoffset] ease-linear starting:[stroke-dashoffset:1]';

/** The colour of the run fills an edge in the time the dot takes to go along it. */
const FILL_STYLE = { transitionDuration: `${TRAVEL_MS}ms` };

/** An edge whose route changed comes back in place with a fade, while the steps travel to their new places. */
const REDRAWN = 'transition-opacity delay-150 duration-300 starting:opacity-0';

const LABEL_TONE: Record<EdgeTone, string> = {
  idle: 'bg-background text-muted-foreground ring-border',
  taken:
    'bg-[color-mix(in_oklab,var(--primary)_10%,var(--background))] text-primary-ink ring-primary/40',
  leftOut: 'bg-background text-muted-foreground ring-border opacity-50',
};

/** An edge is left out when the run never came to it: its step was skipped, or its branch took another output. */
function isLeftOut(run: Run, edge: FlowEdge) {
  const fromStatus = run.steps[edge.fromId]?.status;
  const wasStopped = fromStatus === 'skipped' || fromStatus === 'denied';
  if (wasStopped) {
    return true;
  }
  const choice = run.choices[edge.fromId];
  const isOutput = edge.outputId !== null;
  const hasChosen = choice !== undefined;
  const tookAnother = choice !== edge.outputId;
  return isOutput && hasChosen && tookAnother;
}

function toneOf(run: Run, edge: FlowEdge): EdgeTone {
  if (run.taken.includes(edge.id)) {
    return 'taken';
  }
  if (isLeftOut(run, edge)) {
    return 'leftOut';
  }
  return 'idle';
}

function entranceOf(isNew: boolean, isRedrawn: boolean) {
  if (isNew) {
    return cn(DRAWN, 'duration-500');
  }
  if (isRedrawn) {
    return REDRAWN;
  }
  return undefined;
}

/** Only the run fills an edge. An edge an edit draws again while it is taken shows its colour with the redraw. */
function fillEntranceOf(isFillInherited: boolean) {
  if (isFillInherited) {
    return REDRAWN;
  }
  return DRAWN;
}

type EdgePathProps = {
  edge: FlowEdge;
  tone: EdgeTone;
  isNew: boolean;
  isRedrawn: boolean;
};

/** Drawn again only when its own tone or route changes: a beat of the run touches one or two edges. */
const EdgePath = memo(function EdgePath({
  edge,
  tone,
  isNew,
  isRedrawn,
}: EdgePathProps) {
  const isTaken = tone === 'taken';
  const [isFillInherited, setIsFillInherited] = useState(isTaken);
  const hasLostFill = isFillInherited && !isTaken;
  if (hasLostFill) {
    setIsFillInherited(false);
  }

  return (
    <g
      className={cn('transition-opacity duration-300', TONE_CLASS[tone])}
      fill='none'
    >
      <path
        d={edge.path}
        pathLength={1}
        strokeWidth={1.5}
        className={cn('stroke-foreground/25', entranceOf(isNew, isRedrawn))}
      />
      {isTaken && (
        <path
          d={edge.path}
          pathLength={1}
          strokeWidth={2}
          style={FILL_STYLE}
          className={cn('stroke-primary', fillEntranceOf(isFillInherited))}
        />
      )}
    </g>
  );
});

type EdgeLabelProps = {
  label: string;
  at: Point;
  tone: EdgeTone;
};

/** An output whose name was erased still has to read as an output. */
function shownLabelOf(label: string) {
  if (label.trim() === '') {
    return 'Unnamed';
  }
  return label;
}

/** The label hangs from a point without size, so centring it never widens the plane. */
const EdgeLabel = memo(function EdgeLabel({ label, at, tone }: EdgeLabelProps) {
  const anchorStyle = { translate: `${at.x}px ${at.y}px` };

  return (
    <span
      className='absolute top-0 left-0 size-0 transition-[translate] duration-300 ease-(--ease-out-strong)'
      style={anchorStyle}
    >
      <span
        className={cn(
          'hairline-ring absolute top-0 left-0 flex h-[18px] max-w-44 -translate-x-1/2 -translate-y-1/2 items-center rounded-md px-1.5 text-[11px] font-medium whitespace-nowrap transition-[color,background-color,opacity] duration-300',
          LABEL_TONE[tone]
        )}
      >
        <span className='truncate'>{shownLabelOf(label)}</span>
      </span>
    </span>
  );
});

/** The share of the way reached at each corner of an edge, so the dot keeps one speed along all of it. */
function sharesOf(points: Point[]) {
  const total = lengthOf(points);
  const shares = [0];
  let travelled = 0;
  for (let index = 1; index < points.length; index += 1) {
    const side = [points[index - 1], points[index]];
    travelled += lengthOf(side);
    const share = travelled / total;
    shares.push(share);
  }
  return shares;
}

const DOT_FADE = [0, 1, 1, 0];

const DOT_FADE_TIMES = [0, 0.12, 0.85, 1];

const TRAVEL_SECONDS = TRAVEL_MS / 1000;

type DotRoute = {
  first: Point;
  xs: number[];
  ys: number[];
  times: number[];
};

function routeOf(edge: FlowEdge): DotRoute {
  return {
    first: edge.points[0],
    xs: edge.points.map((point) => point.x),
    ys: edge.points.map((point) => point.y),
    times: sharesOf(edge.points),
  };
}

/**
 * One dot goes along the edge the run just took, once. It moves with a transform and leaves no loop
 * behind. It keeps the route of that moment: an edit that moves the edge later does not send it again.
 */
function TravelDot({ edge }: { edge: FlowEdge }) {
  const [route] = useState(() => routeOf(edge));
  const { first, xs, ys, times } = route;
  const glide: Transition = {
    duration: TRAVEL_SECONDS,
    ease: 'linear',
    times,
  };
  const fade: Transition = {
    duration: TRAVEL_SECONDS,
    times: DOT_FADE_TIMES,
  };

  return (
    <motion.span
      aria-hidden='true'
      initial={{ x: first.x, y: first.y, opacity: 0 }}
      animate={{ x: xs, y: ys, opacity: DOT_FADE }}
      transition={{ x: glide, y: glide, opacity: fade }}
      className='bg-primary pointer-events-none absolute top-0 left-0 -mt-1 -ml-1 size-2 rounded-full'
    />
  );
}

function touches(edge: FlowEdge, stepId: string | null) {
  if (stepId === null) {
    return false;
  }
  return edge.fromId === stepId || edge.toId === stepId;
}

function canTravel(edge: FlowEdge | undefined): edge is FlowEdge {
  if (!edge) {
    return false;
  }
  return lengthOf(edge.points) > 0;
}

type EdgeLayerProps = {
  layout: FlowLayout;
  run: Run;
  /** The text on the edge of each output of a branch, by the id of that edge. */
  labels: Partial<Record<string, string>>;
  /** The step that was just added: the edges that touch it draw themselves. */
  arrivedId: string | null;
  /** True once the flow was edited. Before that, edges are simply there: nothing plays when the page loads. */
  hasEdits: boolean;
};

export const EdgeLayer = memo(function EdgeLayer({
  layout,
  run,
  labels,
  arrivedId,
  hasEdits,
}: EdgeLayerProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const lastTakenId = run.taken.at(-1);
  const lastTaken = layout.edges.find((edge) => edge.id === lastTakenId);
  const showsDot = canTravel(lastTaken) && !shouldReduceMotion;

  return (
    <>
      <svg
        aria-hidden='true'
        width={layout.width}
        height={layout.height}
        className='pointer-events-none absolute top-0 left-0 overflow-visible'
      >
        {layout.edges.map((edge) => (
          <EdgePath
            key={`${edge.id} ${edge.path}`}
            edge={edge}
            tone={toneOf(run, edge)}
            isNew={touches(edge, arrivedId)}
            isRedrawn={hasEdits}
          />
        ))}
      </svg>
      {layout.edges.map((edge) => {
        const label = labels[edge.id];
        if (label === undefined || edge.labelAt === null) {
          return null;
        }
        return (
          <EdgeLabel
            key={edge.id}
            label={label}
            at={edge.labelAt}
            tone={toneOf(run, edge)}
          />
        );
      })}
      {showsDot && lastTaken && (
        <TravelDot key={`${run.token} ${run.taken.length}`} edge={lastTaken} />
      )}
    </>
  );
});

'use client';

import { useRef, useState } from 'react';

import { PlusIcon } from '@/registry/ndeko/lib/icons';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/registry/ndeko/ui/popover';

import { capitalized } from './capitalized';
import type { PaletteEntry } from './catalog';
import { Palette } from './palette';

type InsertButtonProps = {
  /** Where the point sits, from the corner of the step it follows. */
  x: number;
  y: number;
  /** Where a step added here goes, in words that follow "Add a step": after Track the parcel. */
  placement: string;
  onPick: (entry: PaletteEntry) => void;
};

/**
 * A small plus on an edge. It opens the palette beside it, and a pick adds the step right there.
 * The point sits on a zero-size anchor, so centring it never widens the plane.
 */
export function InsertButton({ x, y, placement, onPick }: InsertButtonProps) {
  const [isOpen, setIsOpen] = useState(false);
  const hasPicked = useRef(false);
  const anchorStyle = { translate: `${x}px ${y}px` };

  function pick(entry: PaletteEntry) {
    hasPicked.current = true;
    setIsOpen(false);
    onPick(entry);
  }

  /** After a pick the focus belongs to the new step, which takes it itself. Without one it goes back to the plus. */
  function returnsFocus() {
    const wasPicked = hasPicked.current;
    hasPicked.current = false;
    return !wasPicked;
  }

  return (
    <span className='absolute top-0 left-0 size-0' style={anchorStyle}>
      <Popover open={isOpen} onOpenChange={setIsOpen}>
        <PopoverTrigger
          render={
            <button
              type='button'
              aria-label={`Add a step ${placement}`}
              className='bg-card text-muted-foreground ring-foreground/15 hover:text-foreground hover:ring-foreground/30 focus-visible:ring-ring data-popup-open:bg-primary data-popup-open:text-primary-foreground data-popup-open:ring-primary hairline-ring absolute -top-2 -left-2 flex size-4 cursor-pointer items-center justify-center rounded-full shadow-[0_1px_2px_rgb(0_0_0/0.05)] transition-[color,background-color,box-shadow] duration-150 outline-none after:absolute after:-inset-2 focus-visible:ring-2'
            />
          }
        >
          <PlusIcon className='size-2.5' strokeWidth={2.5} />
        </PopoverTrigger>
        <PopoverContent
          side='right'
          align='start'
          sideOffset={10}
          finalFocus={returnsFocus}
          className='flex max-h-80 w-64 flex-col p-2'
        >
          <Palette
            placement={capitalized(placement)}
            pressed={null}
            onPick={pick}
          />
        </PopoverContent>
      </Popover>
    </span>
  );
}

