      </AnimatePresence>
      <div
        role='toolbar'
        aria-label='Canvas tools'
        className='bg-card hairline-ring ring-border flex max-w-full flex-wrap items-center gap-y-0.5 rounded-xl p-1 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
      >
        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          aria-label='Zoom out'
          onClick={() => zoomBy(-1)}
          className='text-muted-foreground'
