          <ZoomOutIcon />
        </Button>
        <ZoomValue store={store} />
        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          aria-label='Zoom in'
          onClick={() => zoomBy(1)}
          className='text-muted-foreground'
