        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          aria-label='Redo'
          disabled={!canRedo}
          onClick={onRedo}
          className={cn(
            'text-muted-foreground',
            pressedQuietOf(echo === 'redo')
          )}
        >
          <RedoIcon />
        </Button>
        <span aria-hidden='true' className={DIVIDER} />
        <RunFigures lastRun={lastRun} hasRunStarted={hasRunStarted} />
      </div>
    </div>
  );
});

'use client';

import { memo, useEffect, useRef } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

import { ARROW_OFFSET } from './canvas-frame';
import type { Box, FlowLayout } from './layout';
import type { Run, StepStatus } from './run';
import type { Viewport } from './use-viewport';
import type { View } from './viewport';

const MAP_WIDTH = 168;

const MAP_HEIGHT = 128;

type Drag = {
  pointerId: number;
  startX: number;
  startY: number;
  view: View;
};

function toneOf(isSelected: boolean, status: StepStatus | undefined) {
  if (isSelected) {
    return 'bg-primary';
  }
  if (status === 'skipped') {
    return 'bg-foreground/10';
  }
  const isAtWork = status === 'running' || status === 'retrying';
  if (isAtWork) {
    return 'bg-primary/60';
  }
  return 'bg-foreground/25';
}

type MapStepProps = {
  box: Box;
  scale: number;
  tone: string;
};

function MapStep({ box, scale, tone }: MapStepProps) {
  const left = box.x * scale;
  const top = box.y * scale;
  const style = {
    translate: `${left}px ${top}px`,
    width: box.width * scale,
    height: box.height * scale,
  };

  return (
    <span
      style={style}
      className={cn(
        'absolute top-0 left-0 rounded-[2px] transition-[translate,background-color] duration-300 ease-(--ease-out-strong)',
        tone
      )}
    />
  );
}

type MiniMapProps = {
  layout: FlowLayout;
  viewport: Viewport;
  run: Run;
  selectedId: string | null;
  className?: string;
};

/**
 * The whole flow as small rectangles, with the part the canvas shows as a frame. The frame is
 * written to straight from the view, and dragging it pans the canvas.
 */
export const MiniMap = memo(function MiniMap({
  layout,
  viewport,
  run,
  selectedId,
  className,
}: MiniMapProps) {
  const { store, show, panBy } = viewport;
  const frameRef = useRef<HTMLButtonElement>(null);
  const latestViewport = useRef(viewport);
  const drag = useRef<Drag | null>(null);
  const scaleAcross = MAP_WIDTH / layout.width;
  const scaleDown = MAP_HEIGHT / layout.height;
  const scale = Math.min(scaleAcross, scaleDown);
  const mapStyle = {
    width: layout.width * scale,
    height: layout.height * scale,
  };

  useEffect(() => {
    latestViewport.current = viewport;
  });

  /** A pan only moves the frame. Its size is written again when the zoom or the canvas changes size, never on each frame of a drag. */
  useEffect(() => {
    let writtenSize = '';
    function place() {
      const frame = frameRef.current;
      if (!frame) {
        return;
      }
      const view = store.get();
      const size = latestViewport.current.frameSizeOf();
      const ratio = scale / view.zoom;
      const left = -view.x * ratio;
      const top = -view.y * ratio;
      const width = size.width * ratio;
      const height = size.height * ratio;
      const nextSize = `${width} ${height}`;
      frame.style.transform = `translate(${left}px, ${top}px)`;
      if (nextSize === writtenSize) {
        return;
      }
      writtenSize = nextSize;
      frame.style.width = `${width}px`;
      frame.style.height = `${height}px`;
    }
    place();
    return store.subscribe(place);
  }, [store, scale]);

  function startDrag(event: React.PointerEvent<HTMLButtonElement>) {
    event.currentTarget.setPointerCapture(event.pointerId);
    drag.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      view: store.rest(),
    };
  }

  /** A move of the frame on the map is the opposite move of the plane, at the size the plane shows. */
  function dragFrame(event: React.PointerEvent<HTMLButtonElement>) {
    const current = drag.current;
    if (current?.pointerId !== event.pointerId) {
      return;
    }
    const ratio = current.view.zoom / scale;
    const offsetX = (event.clientX - current.startX) * ratio;
    const offsetY = (event.clientY - current.startY) * ratio;
    show({
      x: current.view.x - offsetX,
      y: current.view.y - offsetY,
      zoom: current.view.zoom,
    });
  }

  function endDrag() {
    drag.current = null;
  }

  function panFromKeys(event: React.KeyboardEvent<HTMLButtonElement>) {
    const offset = ARROW_OFFSET[event.key];
    if (offset) {
      event.preventDefault();
      panBy(offset.x, offset.y);
    }
  }

  return (
    <div
      data-solid
      data-canvas-overlay='map'
      className={cn(
        'bg-card hairline-ring ring-border pointer-events-auto rounded-xl p-2 shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
        className
      )}
    >
      <div className='relative overflow-hidden' style={mapStyle}>
        {layout.boxes.map((box) => (
          <MapStep
            key={box.id}
            box={box}
            scale={scale}
            tone={toneOf(box.id === selectedId, run.steps[box.id]?.status)}
          />
        ))}
        <button
          ref={frameRef}
          type='button'
          aria-label='The part of the flow in view. Drag it, or use the arrow keys, to move the canvas'
          onPointerDown={startDrag}
          onPointerMove={dragFrame}
          onPointerUp={endDrag}
          onPointerCancel={endDrag}
          onKeyDown={panFromKeys}
          className='bg-primary/10 ring-primary/60 focus-visible:ring-primary absolute top-0 left-0 cursor-grab touch-none rounded-[3px] ring-1 outline-none ring-inset focus-visible:ring-2 active:cursor-grabbing'
        />
      </div>
    </div>
  );
});

'use client';

import { useId } from 'react';

import { MousePointerClickIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Tabs, TabsList, TabsPanel, TabsTab } from '@/registry/ndeko/ui/tabs';

import { stepOf } from './flow';
import {
  AgentFields,
  ApprovalFields,
  LoopFields,
  ProductFields,
  WaitFields,
} from './inspector-fields';
import { BranchFields } from './inspector-outputs';
import { LastRunPanel } from './inspector-run';
import { VariablesPanel } from './inspector-variables';
import { isEscapeInside } from './keys';
import { isProductStep, KIND_WORD, type Step, type Workflow } from './model';
import { StepTile } from './node-tile';
import type { Run } from './run';
import type { BuilderAction, InspectorTab } from './session';
import { differsFromSaved } from './session-setup';

const TABS: InspectorTab[] = ['setup', 'variables', 'run'];

/** The panel is positioned: a word kept for screen readers inside it would widen the page otherwise. */
const PANEL = 'relative -mx-1 flex min-h-0 flex-col overflow-y-auto px-1 pb-1';

type SetupPanelProps = {
  step: Step;
  onAct: (action: BuilderAction) => void;
  onMintId: () => string;
};

/** Each kind of step has its own setup. Every change applies at once, and the flow reads as unsaved until it is saved. */
function SetupPanel({ step, onAct, onMintId }: SetupPanelProps) {
  const { id } = step;

  if (step.kind === 'agent') {
    return (
      <AgentFields
        step={step}
        onChange={(patch) => onAct({ type: 'agentChanged', id, patch })}
      />
    );
  }
  function addOutput() {
    const outputId = onMintId();
    onAct({ type: 'outputAdded', id, outputId });
  }

  if (step.kind === 'branch') {
    return (
      <BranchFields
        step={step}
        onAdd={addOutput}
        onRename={(outputId, label) =>
          onAct({ type: 'outputRenamed', id, outputId, label })
        }
        onRemove={(outputId) => onAct({ type: 'outputRemoved', id, outputId })}
      />
    );
  }
  if (step.kind === 'approval') {
    return (
      <ApprovalFields
        step={step}
        onChange={(patch) => onAct({ type: 'approvalChanged', id, patch })}
      />
    );
  }
  if (step.kind === 'wait') {
    return (
      <WaitFields
        step={step}
        onChange={(duration) => onAct({ type: 'waitChanged', id, duration })}
      />
    );
  }
  if (step.kind === 'loop') {
    return (
      <LoopFields
        step={step}
        onChange={(rounds) => onAct({ type: 'loopChanged', id, rounds })}
      />
    );
  }
  if (isProductStep(step)) {
    return (
      <ProductFields
        step={step}
        onPickAction={(actionId) =>
          onAct({ type: 'actionPicked', id, actionId })
        }
        onChangeField={(fieldId, value) =>
          onAct({ type: 'fieldChanged', id, fieldId, value })
        }
      />
    );
  }
  return null;
}

/** The dot beside Last run tells the step has something to show there. */
function hasRunMark(run: Run, step: Step) {
  const status = run.steps[step.id]?.status;
  return status !== undefined && status !== 'skipped';
}

type InspectorProps = {
  workflow: Workflow;
  savedWorkflow: Workflow;
  selectedId: string | null;
  tab: InspectorTab;
  run: Run;
  /** False off screen: a text that streams holds its place. */
  isActive: boolean;
  onAct: (action: BuilderAction) => void;
  onMintId: () => string;
  /** Escape gives the focus back to the step on the canvas. */
  onLeave: () => void;
  className?: string;
};

export function Inspector({
  workflow,
  savedWorkflow,
  selectedId,
  tab,
  run,
  isActive,
  onAct,
  onMintId,
  onLeave,
  className,
}: InspectorProps) {
  const headingId = useId();
  const step = stepOf(workflow, selectedId);

  function leaveOnEscape(event: React.KeyboardEvent<HTMLElement>) {
    if (isEscapeInside(event)) {
      onLeave();
    }
  }

  function changeTab(next: unknown) {
    const found = TABS.find((candidate) => candidate === next);
    if (found) {
      onAct({ type: 'tabPicked', tab: found });
    }
  }

  if (!step) {
    return (
      <section
        aria-labelledby={headingId}
        onKeyDown={leaveOnEscape}
        className={cn('flex min-h-0 flex-col', className)}
      >
        <div className='m-auto flex max-w-56 flex-col items-center gap-3 py-6 text-center'>
          <span
            aria-hidden='true'
            className='keycap-3d text-muted-foreground inline-flex size-9 items-center justify-center rounded-lg'
          >
            <MousePointerClickIcon className='size-4' />
          </span>
          <h2
            id={headingId}
            tabIndex={-1}
            data-inspector-heading
            className='text-sm font-medium outline-none'
          >
            No step selected
          </h2>
          <p className='text-muted-foreground text-[13px] leading-relaxed'>
            Pick a step on the canvas to set it up, see what it can read and
            what it did in the last run
          </p>
        </div>
      </section>
    );
  }

  const savedStep = stepOf(savedWorkflow, step.id);
  const canReset = differsFromSaved(step, savedStep);
  const showsRunMark = hasRunMark(run, step);

  return (
    <section
      aria-labelledby={headingId}
      onKeyDown={leaveOnEscape}
      className={cn('flex min-h-0 flex-col gap-3', className)}
    >
      <header className='flex min-h-9 shrink-0 items-center gap-2.5'>
        <StepTile step={step} />
        <div className='flex min-w-0 flex-1 flex-col leading-tight'>
          <span className='text-muted-foreground text-[11px]'>
            {KIND_WORD[step.kind]}
          </span>
          <h2
            id={headingId}
            tabIndex={-1}
            data-inspector-heading
            className='focus-visible:ring-ring/25 truncate rounded-sm text-sm font-medium outline-none focus-visible:ring-[3px]'
          >
            {step.name}
          </h2>
        </div>
        {canReset && (
          <Button
            type='button'
            variant='link'
            size='sm'
            aria-label={`Reset ${step.name} to its saved values`}
            onClick={() => onAct({ type: 'stepReset', id: step.id })}
            className='shrink-0 px-1 transition-opacity duration-200 starting:opacity-0'
          >
            Reset
          </Button>
        )}
      </header>
      <Tabs
        value={tab}
        onValueChange={changeTab}
        className='min-h-0 flex-1 gap-3'
      >
        <TabsList
          variant='segmented'
          aria-label='About this step'
          className='w-full shrink-0'
        >
          <TabsTab value='setup' className='flex-1'>
            Setup
          </TabsTab>
          <TabsTab value='variables' className='flex-1'>
            Variables
          </TabsTab>
          <TabsTab value='run' className='flex-1'>
            Last run
            {showsRunMark && (
              <span className='bg-primary size-1.5 rounded-full'>
                <span className='sr-only'>, has a result</span>
              </span>
            )}
          </TabsTab>
        </TabsList>
        <TabsPanel value='setup' className={PANEL}>
          <SetupPanel
            key={step.id}
            step={step}
            onAct={onAct}
            onMintId={onMintId}
          />
        </TabsPanel>
        <TabsPanel value='variables' className={PANEL}>
          <VariablesPanel workflow={workflow} step={step} />
        </TabsPanel>
        <TabsPanel value='run' className={PANEL}>
          <LastRunPanel step={step} run={run} isActive={isActive} />
        </TabsPanel>
      </Tabs>
    </section>
  );
}

'use client';

import { useId } from 'react';

import { Input } from '@/registry/ndeko/ui/input';
import { Label, LABEL_RECIPE } from '@/registry/ndeko/ui/label';
import { Segments } from '@/registry/ndeko/ui/segments';
import { Textarea } from '@/registry/ndeko/ui/textarea';

import { CREATIVITIES, ROUNDS, TIMEOUT_RULES, TIMEOUTS, WAITS } from './data';
import {
  ApproverSelect,
  ChoiceSelect,
  FIELD,
  GROUP,
  HINT,
  ModelSelect,
  SwitchRow,
} from './field-kit';
import type {
  AgentSetup,
  AgentStep,
  ApprovalSetup,
  ApprovalStep,
  LoopRounds,
  LoopStep,
  ProductStep,
  WaitDuration,
  WaitStep,
} from './model';
import { MarkTile } from './node-tile';
import { actionOf, toolOf, type ToolField } from './tools';

/** A name other steps read between braces: letters, figures and underscores only. */
function variableNameOf(typed: string) {
  return typed.replace(/[^a-zA-Z0-9_]/g, '_');
}

type AgentFieldsProps = {
  step: AgentStep;
  onChange: (patch: Partial<AgentSetup>) => void;
};

export function AgentFields({ step, onChange }: AgentFieldsProps) {
  const instructionsId = useId();
  const outputId = useId();
  const outputHintId = useId();
  const { agent } = step;

  function renameOutput(event: React.ChangeEvent<HTMLInputElement>) {
    const outputName = variableNameOf(event.target.value);
    onChange({ outputName });
  }

  return (
    <div className={GROUP}>
      <div className={FIELD}>
        <Label htmlFor={instructionsId}>Instructions</Label>
        <Textarea
          id={instructionsId}
          value={agent.instructions}
          placeholder='Say what this agent does with what it receives'
          onChange={(event) => onChange({ instructions: event.target.value })}
          className='min-h-24'
        />
      </div>
      <ModelSelect
        value={agent.modelId}
        onChange={(modelId) => onChange({ modelId })}
      />
      <div className={FIELD}>
        <span className={LABEL_RECIPE}>Creativity</span>
        <Segments
          label='Creativity'
          value={agent.creativity}
          segments={CREATIVITIES}
          onValueChange={(creativity) => onChange({ creativity })}
          className='w-full'
        />
      </div>
      <div className='flex flex-col gap-3'>
        <SwitchRow
          label='Stream the answer'
          hint='Words show as they are written'
          isOn={agent.streams}
          onChange={(streams) => onChange({ streams })}
        />
        <SwitchRow
          label='Remember the thread'
          hint='Earlier emails of the customer are read first'
          isOn={agent.remembers}
          onChange={(remembers) => onChange({ remembers })}
        />
        <SwitchRow
          label='Retry once on failure'
          hint='One more try before the run stops'
          isOn={agent.retries}
          onChange={(retries) => onChange({ retries })}
        />
      </div>
      <div className={FIELD}>
        <Label htmlFor={outputId}>Output name</Label>
        <Input
          id={outputId}
          value={agent.outputName}
          aria-describedby={outputHintId}
          onChange={renameOutput}
          className='font-mono'
        />
        <p id={outputHintId} className={HINT}>
          Later steps read it as{' '}
          <code className='font-mono'>{`{{${agent.outputName}}}`}</code>
        </p>
      </div>
    </div>
  );
}

type ApprovalFieldsProps = {
  step: ApprovalStep;
  onChange: (patch: Partial<ApprovalSetup>) => void;
};

export function ApprovalFields({ step, onChange }: ApprovalFieldsProps) {
  const { approval } = step;

  return (
    <div className={GROUP}>
      <ApproverSelect
        value={approval.approverId}
        onChange={(approverId) => onChange({ approverId })}
      />
      <ChoiceSelect
        label='If nobody answers'
        value={approval.timeoutHours}
        choices={TIMEOUTS}
        onChange={(timeoutHours) => onChange({ timeoutHours })}
      />
      <ChoiceSelect
        label='Then'
        value={approval.onTimeout}
        choices={TIMEOUT_RULES}
        onChange={(onTimeout) => onChange({ onTimeout })}
      />
    </div>
  );
}

type ToolFieldRowProps = {
  field: ToolField;
  value: string;
  onChange: (fieldId: string, value: string) => void;
};

function ToolFieldRow({ field, value, onChange }: ToolFieldRowProps) {
  const inputId = useId();

  return (
    <div className={FIELD}>
      <Label htmlFor={inputId}>{field.label}</Label>
      <Input
        id={inputId}
        value={value}
        onChange={(event) => onChange(field.id, event.target.value)}
      />
    </div>
  );
}

/** A trigger listens for an event of its product. A tool or an output runs one of its actions. */
function actionLabelOf(isTrigger: boolean) {
  if (isTrigger) {
    return 'Event';
  }
  return 'Action';
}

type ProductFieldsProps = {
  step: ProductStep;
  onPickAction: (actionId: string) => void;
  onChangeField: (fieldId: string, value: string) => void;
};

export function ProductFields({
  step,
  onPickAction,
  onChangeField,
}: ProductFieldsProps) {
  const tool = toolOf(step.tool.toolId);
  const action = actionOf(tool, step.tool.actionId);
  const isTrigger = step.kind === 'trigger';
  const offered = tool.actions.filter((entry) => entry.isEvent === isTrigger);
  const choices = offered.map((entry) => ({
    value: entry.id,
    label: entry.label,
  }));

  return (
    <div className={GROUP}>
      <div className='bg-foreground/[0.04] flex items-center gap-2 rounded-lg p-2'>
        <MarkTile mark={tool.mark} size='md' />
        <span className='min-w-0 truncate text-[13px] font-medium'>
          {tool.name}
        </span>
      </div>
      <ChoiceSelect
        label={actionLabelOf(isTrigger)}
        value={action.id}
        choices={choices}
        onChange={onPickAction}
      />
      {action.fields.map((field) => (
        <ToolFieldRow
          key={`${action.id} ${field.id}`}
          field={field}
          value={step.tool.values[field.id] ?? ''}
          onChange={onChangeField}
        />
      ))}
    </div>
  );
}

type WaitFieldsProps = {
  step: WaitStep;
  onChange: (duration: WaitDuration) => void;
};

export function WaitFields({ step, onChange }: WaitFieldsProps) {
  return (
    <div className={GROUP}>
      <ChoiceSelect
        label='Wait for'
        value={step.duration}
        choices={WAITS}
        onChange={onChange}
      />
      <p className={HINT}>A test run does not wait: it goes straight on</p>
    </div>
  );
}

type LoopFieldsProps = {
  step: LoopStep;
  onChange: (rounds: LoopRounds) => void;
};

export function LoopFields({ step, onChange }: LoopFieldsProps) {
  return (
    <div className={GROUP}>
      <ChoiceSelect
        label='Repeat what follows'
        value={step.rounds}
        choices={ROUNDS}
        onChange={onChange}
      />
      <p className={HINT}>A test run plays one round</p>
    </div>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId, useRef } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { PlusIcon, Trash2Icon } from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
