import { useEffect } from 'react';

import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';

import type { Workflow } from './model';
import { delayOf, type Run } from './run';

/**
 * Plays a run beat by beat, the way a backend would stream it: each beat is asked for once the one
 * before it has had its time. Nothing ticks off screen, in a hidden tab, or while the run waits.
 */
export function useRunClock(
  run: Run,
  workflow: Workflow,
  isOnScreen: boolean,
  onBeat: (token: number, beat: number) => void
) {
  const isVisible = useDocumentVisible();
  const delay = delayOf(run, workflow);
  const { token, beat } = run;
  const isPlaying = isOnScreen && isVisible;

  useEffect(() => {
    if (delay === null || !isPlaying) {
      return;
    }
    const timer = setTimeout(() => onBeat(token, beat), delay);
    return () => clearTimeout(timer);
  }, [delay, isPlaying, token, beat, onBeat]);
}

'use client';

import { useCallback, type RefObject } from 'react';

export const CANVAS_FRAME = '[data-canvas-frame]';

export const INSPECTOR_HEADING = '[data-inspector-heading]';

/**
 * What takes the focus is often drawn by the very change that asks for it: a step that was just
 * added, a sheet that opens. It is looked up once the page has been drawn again, inside the template only.
 */
export function useFocusLater(ref: RefObject<HTMLElement | null>) {
  const focusLater = useCallback(
    (selector: string) => {
      requestAnimationFrame(() => {
        const target = ref.current?.querySelector<HTMLElement>(selector);
        target?.focus();
      });
    },
    [ref]
  );

  const focusNode = useCallback(
    (id: string) => {
      focusLater(`[data-node="${id}"]`);
    },
    [focusLater]
  );

  return { focusLater, focusNode };
}

'use client';

import { useState } from 'react';

/**
 * The value as it was when its key last changed. What reads it draws again only when the key does:
 * the instructions of a step typed key by key leave the canvas as it was.
 */
export function useKept<Value>(value: Value, key: string): Value {
  const [kept, setKept] = useState({ key, value });
  const isStale = kept.key !== key;
  if (isStale) {
    setKept({ key, value });
    return value;
  }
  return kept.value;
}

'use client';

import { useCallback, useLayoutEffect, useRef, type RefObject } from 'react';

import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { usePress } from '@/registry/ndeko/lib/demonstration';

import type { PaletteEntry } from './catalog';
import { previousOf } from './flow';
import type { InsertAt, Workflow } from './model';
import { waitingIdOf, type Decision } from './run';
import { sampleOf, type Sample, type SampleId } from './samples';
import { SAVE_MS } from './script';
import type { BuilderAction, BuilderState } from './session';
import {
  CANVAS_FRAME,
  INSPECTOR_HEADING,
  useFocusLater,
} from './use-focus-later';

/** How long the line "Step removed, Undo" stays in the tool bar. */
const NOTICE_MS = 6000;

/** A step picked in the palette goes after the selected one, or at the end of the flow when none is. */
export function paletteTargetOf(selectedId: string | null): InsertAt {
  if (selectedId === null) {
    return { at: 'end' };
  }
  return { at: 'after', stepId: selectedId };
}

export type Backend = {
  onRun?: (workflow: Workflow, sample: Sample) => void;
  onSave?: (workflow: Workflow) => void;
  onPublish?: (workflow: Workflow) => void;
  onApprove?: (stepId: string) => void;
  onDeny?: (stepId: string) => void;
};

type HandlerContext = {
  state: BuilderState;
  act: (action: BuilderAction) => void;
  hasInspectorSheet: boolean;
  hasPaletteSheet: boolean;
  backend: Backend;
};

/**
 * What a person does on the builder. The handlers read the state at the moment they run, so they
 * keep their identity, and the memoised canvas, top bar and tool bar stay still while a step is typed into.
 */
export function useBuilderHandlers(
  rootRef: RefObject<HTMLElement | null>,
  { state, act, hasInspectorSheet, hasPaletteSheet, backend }: HandlerContext
) {
  const { onRun, onSave, onPublish, onApprove, onDeny } = backend;
  const { schedule } = useTimeouts();
  const { focusLater, focusNode } = useFocusLater(rootRef);
  const { pressed: echo, press: echoKey } = usePress<'undo' | 'redo'>();
  const mintedCount = useRef(0);
  const latest = useRef(state);

  useLayoutEffect(() => {
    latest.current = state;
  });

  const mintId = useCallback(() => {
    mintedCount.current += 1;
    return `step-${mintedCount.current}`;
  }, []);

  /** In the sheet of a narrow page a pick closes the sheet, and the focus goes to the step that arrived. */
  const pickEntry = useCallback(
    (entry: PaletteEntry) => {
      const id = mintId();
      const at = paletteTargetOf(latest.current.selectedId);
      act({ type: 'stepAdded', entryId: entry.id, at, id });
      if (hasPaletteSheet) {
        act({ type: 'paletteSheet', isOpen: false });
        focusNode(id);
      }
    },
    [act, mintId, focusNode, hasPaletteSheet]
  );

  /** Enter or Space on a step moves the focus to the heading of its setup. A tap only selects. */
  const select = useCallback(
    (id: string, isFromKeyboard: boolean) => {
      act({ type: 'selected', id });
      if (!isFromKeyboard) {
        return;
      }
      if (hasInspectorSheet) {
        act({ type: 'inspectorSheet', isOpen: true });
      }
      focusLater(INSPECTOR_HEADING);
    },
    [act, hasInspectorSheet, focusLater]
  );

  /** Escape in the setup gives the focus back to the step it belongs to. */
  const leaveInspector = useCallback(() => {
    const { selectedId } = latest.current;
    if (hasInspectorSheet) {
      act({ type: 'inspectorSheet', isOpen: false });
    }
    if (selectedId === null) {
      focusLater(CANVAS_FRAME);
      return;
    }
    focusNode(selectedId);
  }, [act, hasInspectorSheet, focusLater, focusNode]);

  const openInspector = useCallback(() => {
    act({ type: 'inspectorSheet', isOpen: true });
    focusLater(INSPECTOR_HEADING);
  }, [act, focusLater]);

  const openPalette = useCallback(() => {
    act({ type: 'paletteSheet', isOpen: true });
    focusLater('[data-sheet-close="palette"]');
  }, [act, focusLater]);

  const closePalette = useCallback(() => {
    act({ type: 'paletteSheet', isOpen: false });
    focusLater('[data-sheet-open="palette"]');
  }, [act, focusLater]);

  const forgetNoticeLater = useCallback(() => {
    const token = latest.current.noticeCount + 1;
    schedule(() => act({ type: 'noticeCleared', token }), NOTICE_MS);
  }, [act, schedule]);

  /** The step leaves with its button, so the focus goes to the step read just before it. */
  const remove = useCallback(
    (id: string) => {
      const previous = previousOf(latest.current.workflow, id);
      act({ type: 'stepRemoved', id });
      forgetNoticeLater();
      if (previous) {
        focusNode(previous.id);
        return;
      }
      focusLater(CANVAS_FRAME);
    },
    [act, forgetNoticeLater, focusNode, focusLater]
  );

  const duplicate = useCallback(
    (id: string) => {
      const copyId = mintId();
      act({ type: 'stepDuplicated', id, copyId });
      focusNode(copyId);
    },
    [act, mintId, focusNode]
  );

  const insert = useCallback(
    (at: InsertAt, entry: PaletteEntry) => {
      const id = mintId();
      act({ type: 'stepAdded', entryId: entry.id, at, id });
      focusNode(id);
    },
    [act, mintId, focusNode]
  );

  const renameStep = useCallback(
    (id: string, name: string) => {
      act({ type: 'stepRenamed', id, name });
    },
    [act]
  );

  const renameWorkflow = useCallback(
    (name: string) => {
      act({ type: 'workflowRenamed', name });
    },
    [act]
  );

  const undo = useCallback(() => {
    act({ type: 'undone' });
  }, [act]);

  const redo = useCallback(() => {
    act({ type: 'redone' });
  }, [act]);

  /** The line that offered Undo leaves once it is pressed, so the focus goes to the step it brought back. */
  const undoFromNotice = useCallback(() => {
    const restoredId = latest.current.notice?.restoresId ?? null;
    undo();
    if (restoredId === null) {
      focusLater(CANVAS_FRAME);
      return;
    }
    focusNode(restoredId);
  }, [undo, focusLater, focusNode]);

  const undoFromKeys = useCallback(() => {
    undo();
    echoKey('undo');
  }, [undo, echoKey]);

  const redoFromKeys = useCallback(() => {
    redo();
    echoKey('redo');
  }, [redo, echoKey]);

  /** A backend would answer the save itself: here it comes back after a moment. */
  const save = useCallback(() => {
    act({ type: 'saveStarted' });
    schedule(() => act({ type: 'saved' }), SAVE_MS);
    onSave?.(latest.current.workflow);
  }, [act, schedule, onSave]);

  const publish = useCallback(
    (isLive: boolean) => {
      act({ type: 'published', isLive });
      forgetNoticeLater();
      if (isLive) {
        onPublish?.(latest.current.workflow);
      }
    },
    [act, forgetNoticeLater, onPublish]
  );

  const startRun = useCallback(
    (sampleId: SampleId) => {
      act({ type: 'runStarted', sampleId });
      onRun?.(latest.current.workflow, sampleOf(sampleId));
    },
    [act, onRun]
  );

  /** Test run in the top bar sends the email of the last run again. */
  const runAgain = useCallback(() => {
    startRun(latest.current.run.sampleId);
  }, [startRun]);

  const clearRun = useCallback(() => {
    act({ type: 'runCleared' });
  }, [act]);

  /** The two buttons leave with the card, so the focus goes to the step, which now says what was decided. */
  const decide = useCallback(
    (decision: Decision) => {
      const stepId = waitingIdOf(latest.current.run);
      act({ type: 'decided', decision });
      if (stepId === null) {
        return;
      }
      focusNode(stepId);
      if (decision === 'approved') {
        onApprove?.(stepId);
        return;
      }
      onDeny?.(stepId);
    },
    [act, focusNode, onApprove, onDeny]
  );

  return {
    echo,
    mintId,
    pickEntry,
    select,
    leaveInspector,
    openInspector,
    openPalette,
    closePalette,
    remove,
    duplicate,
    insert,
    renameStep,
    renameWorkflow,
    undo,
    redo,
    undoFromNotice,
    undoFromKeys,
    redoFromKeys,
    save,
    publish,
    startRun,
    runAgain,
    clearRun,
    decide,
  };
}

/**
 * True for Escape pressed inside the element that listens. A list opened from a field is drawn
 * outside its panel, yet its keys still reach the panel: Escape there closes the list and nothing else.
 */
export function isEscapeInside(event: React.KeyboardEvent<HTMLElement>) {
  const target = event.target;
  const isInside =
    target instanceof Node && event.currentTarget.contains(target);
  return event.key === 'Escape' && isInside;
}

/** "after Track the parcel" as the start of a line: "After Track the parcel". */
export function capitalized(text: string) {
  const first = text.charAt(0);
  const rest = text.slice(1);
  return `${first.toUpperCase()}${rest}`;
}

import { WORKFLOW } from './data';
import type {
  AgentSetup,
  ApprovalSetup,
  InsertAt,
  LoopRounds,
  WaitDuration,
  Workflow,
} from './model';
import {
  clearedRun,
  IDLE_RUN,
  isBusy,
  isOver,
  startedRun,
  type Decision,
  type Run,
} from './run';
import { advancedRun, decidedRun, type Outcome } from './run-beats';
import { sampleOf, type SampleId } from './samples';
import {
  stepAdded,
  stepDuplicated,
  stepRemoved,
  stepRenamed,
  workflowRenamed,
} from './session-edits';
import { redone, undone } from './session-history';
import {
  actionPicked,
  agentChanged,
  approvalChanged,
  fieldChanged,
  loopChanged,
  outputAdded,
  outputRemoved,
  outputRenamed,
  stepReset,
  waitChanged,
} from './session-setup';

export type InspectorTab = 'setup' | 'variables' | 'run';

/** One line in the tool bar about what just happened, with a way back when there is one. */
export type Notice = {
  token: number;
  text: string;
  canUndo: boolean;
  /** The step an Undo brings back, so it is selected again. */
  restoresId: string | null;
};

/** `at` is null for the save the sample data starts from: it reads "Saved 2 min ago" and never ticks. */
export type SaveState = {
  status: 'saved' | 'saving';
  at: number | null;
};

export type RunTotals = {
  durationMs: number;
  costUsd: number;
};

/** A moment of a run the script waits for: the reply starts to stream, or the run has nothing left to play. */
export type Cue = 'reply' | 'settled';

export type BuilderState = {
  workflow: Workflow;
  /** The flow as it was last saved: what Reset gives back, and what "unsaved" is measured against. */
  savedWorkflow: Workflow;
  /** The flow as it was when Save was pressed. A change made while it saves stays unsaved. */
  savingWorkflow: Workflow | null;
  save: SaveState;
  isLive: boolean;
  past: Workflow[];
  future: Workflow[];
  lastEditKey: string | null;
  selectedId: string | null;
  /** The step that was just added: it grows into place and its edges draw themselves. */
  arrivedId: string | null;
  tab: InspectorTab;
  /** The inspector goes to the step that streams, until a person picks a step or a tab themselves. */
  isFollowingRun: boolean;
  run: Run;
  lastRun: RunTotals | null;
  notice: Notice | null;
  noticeCount: number;
  spoken: string;
  cuesPassed: number;
  isPaletteOpen: boolean;
  isInspectorOpen: boolean;
};

export type BuilderAction =
  | { type: 'selected'; id: string | null }
  | { type: 'tabPicked'; tab: InspectorTab }
  | { type: 'paletteSheet'; isOpen: boolean }
  | { type: 'inspectorSheet'; isOpen: boolean }
  | {
      type: 'stepAdded';
      entryId: string;
      at: InsertAt;
      id: string;
      name?: string;
    }
  | { type: 'stepRemoved'; id: string }
  | { type: 'stepDuplicated'; id: string; copyId: string }
  | { type: 'stepRenamed'; id: string; name: string }
  | { type: 'workflowRenamed'; name: string }
  | { type: 'agentChanged'; id: string; patch: Partial<AgentSetup> }
  | { type: 'approvalChanged'; id: string; patch: Partial<ApprovalSetup> }
  | { type: 'actionPicked'; id: string; actionId: string }
  | { type: 'fieldChanged'; id: string; fieldId: string; value: string }
  | { type: 'waitChanged'; id: string; duration: WaitDuration }
  | { type: 'loopChanged'; id: string; rounds: LoopRounds }
  | { type: 'outputAdded'; id: string; outputId: string }
  | { type: 'outputRenamed'; id: string; outputId: string; label: string }
  | { type: 'outputRemoved'; id: string; outputId: string }
  | { type: 'stepReset'; id: string }
  | { type: 'undone' }
  | { type: 'redone' }
  | { type: 'noticeCleared'; token: number }
  | { type: 'saveStarted' }
  | { type: 'saved' }
  | { type: 'published'; isLive: boolean }
  | { type: 'runStarted'; sampleId: SampleId }
  | { type: 'runAdvanced'; token: number; beat: number }
  | { type: 'decided'; decision: Decision }
  | { type: 'runCleared' }
  | { type: 'cuePassed'; cue: Cue };

export const INITIAL: BuilderState = {
  workflow: WORKFLOW,
  savedWorkflow: WORKFLOW,
  savingWorkflow: null,
  save: { status: 'saved', at: null },
  isLive: false,
  past: [],
  future: [],
  lastEditKey: null,
  selectedId: null,
  arrivedId: null,
  tab: 'setup',
  isFollowingRun: false,
  run: IDLE_RUN,
  lastRun: null,
  notice: null,
  noticeCount: 0,
  spoken: '',
  cuesPassed: 0,
  isPaletteOpen: false,
  isInspectorOpen: false,
};

/** Read by content: a Reset, or an edit that puts back what was saved, leaves nothing to save. */
export function hasUnsavedChanges(state: BuilderState) {
  if (state.workflow === state.savedWorkflow) {
    return false;
  }
  const current = JSON.stringify(state.workflow);
  const saved = JSON.stringify(state.savedWorkflow);
  return current !== saved;
}

/** A pick breaks the run of edits that continue one another: typing again later is another step of the history. */
function selected(state: BuilderState, id: string | null): BuilderState {
  return { ...state, selectedId: id, isFollowingRun: false, lastEditKey: null };
}

function saveStarted(state: BuilderState): BuilderState {
  if (state.save.status === 'saving') {
    return state;
  }
  return {
    ...state,
    savingWorkflow: state.workflow,
    save: { status: 'saving', at: state.save.at },
  };
}

function saved(state: BuilderState, now: number): BuilderState {
  const sent = state.savingWorkflow;
  const isSaving = state.save.status === 'saving';
  if (!isSaving || sent === null) {
    return state;
  }
  return {
    ...state,
    savedWorkflow: sent,
    savingWorkflow: null,
    save: { status: 'saved', at: now },
    lastEditKey: null,
    spoken: 'Saved',
  };
}

const LIVE_LINE = 'Live. Every new email now runs through this workflow';

const DRAFT_LINE = 'Back to draft. New emails wait until you publish again';

function publishLineOf(isLive: boolean) {
  if (isLive) {
    return LIVE_LINE;
  }
  return DRAFT_LINE;
}

/** Going live or back to draft is confirmed in words, in the tool bar and to a screen reader. */
function published(state: BuilderState, isLive: boolean): BuilderState {
  if (isLive === state.isLive) {
    return state;
  }
  const noticeCount = state.noticeCount + 1;
  const text = publishLineOf(isLive);
  const notice: Notice = {
    token: noticeCount,
    text,
    canUndo: false,
    restoresId: null,
  };
  return { ...state, isLive, notice, noticeCount, spoken: text };
}

function noticeCleared(state: BuilderState, token: number): BuilderState {
  if (state.notice?.token !== token) {
    return state;
  }
  return { ...state, notice: null };
}

function totalsOf(run: Run): RunTotals {
  return { durationMs: run.durationMs, costUsd: run.costUsd };
}

function spokenAfter(before: string, spoken: string) {
  if (spoken === '') {
    return before;
  }
  return spoken;
}

/** What a beat of the run changes around it: the inspector follows a step that streams, and a finished run leaves its totals. */
function withOutcome(state: BuilderState, outcome: Outcome): BuilderState {
  const { run } = outcome;
  const isNewStream = run.streamingId !== state.run.streamingId;
  const startsStreaming = isNewStream && run.streamingId !== null;
  const followsStream = startsStreaming && state.isFollowingRun;
  const hasJustEnded = isOver(run) && !isOver(state.run);
  let next: BuilderState = {
    ...state,
    run,
    spoken: spokenAfter(state.spoken, outcome.spoken),
  };
  if (followsStream) {
    next = { ...next, selectedId: run.streamingId, tab: 'run' };
  }
  if (hasJustEnded) {
    next = { ...next, lastRun: totalsOf(run) };
  }
  return next;
}

function runStarted(state: BuilderState, sampleId: SampleId): BuilderState {
  if (isBusy(state.run)) {
    return state;
  }
  const sample = sampleOf(sampleId);
  const run = startedRun(state.run, state.workflow, sampleId);
  const spoken = `Test run started with the email from ${sample.from}`;
  return withOutcome({ ...state, isFollowingRun: true }, { run, spoken });
}

function runAdvanced(
  state: BuilderState,
  token: number,
  beat: number
): BuilderState {
  const isNextBeat = token === state.run.token && beat === state.run.beat;
  if (!isNextBeat) {
    return state;
  }
  const outcome = advancedRun(state.run, state.workflow);
  return withOutcome(state, outcome);
}

function decided(state: BuilderState, decision: Decision): BuilderState {
  const outcome = decidedRun(state.run, state.workflow, decision);
  return withOutcome(state, outcome);
}

function runCleared(state: BuilderState): BuilderState {
  if (isBusy(state.run)) {
    return state;
  }
  return { ...state, run: clearedRun(state.run) };
}

export function isCueOpen(state: BuilderState, cue: Cue) {
  if (!isBusy(state.run)) {
    return true;
  }
  if (cue === 'reply') {
    return state.run.streamingId !== null;
  }
  return false;
}

/** More beats than any run of the sample flow has: the walk to a cue always ends. */
const CUE_BEAT_LIMIT = 200;

/**
 * Live, the script waits for a cue and this only counts it. When the resting state is worked out
 * no clock plays the run, so the run is walked here up to the cue.
 */
function cuePassed(state: BuilderState, cue: Cue): BuilderState {
  let next = state;
  for (let beats = 0; beats < CUE_BEAT_LIMIT; beats += 1) {
    if (isCueOpen(next, cue)) {
      break;
    }
    next = runAdvanced(next, next.run.token, next.run.beat);
  }
  return { ...next, cuesPassed: state.cuesPassed + 1 };
}

export function applyAt(
  state: BuilderState,
  action: BuilderAction,
  now: number
): BuilderState {
  switch (action.type) {
    case 'selected':
      return selected(state, action.id);
    case 'tabPicked':
      return { ...state, tab: action.tab, isFollowingRun: false };
    case 'paletteSheet':
      return { ...state, isPaletteOpen: action.isOpen };
    case 'inspectorSheet':
      return { ...state, isInspectorOpen: action.isOpen };
    case 'stepAdded':
      return stepAdded(
        state,
        action.entryId,
        action.at,
        action.id,
        action.name
      );
    case 'stepRemoved':
      return stepRemoved(state, action.id);
    case 'stepDuplicated':
      return stepDuplicated(state, action.id, action.copyId);
    case 'stepRenamed':
      return stepRenamed(state, action.id, action.name);
    case 'workflowRenamed':
      return workflowRenamed(state, action.name);
    case 'agentChanged':
      return agentChanged(state, action.id, action.patch);
    case 'approvalChanged':
      return approvalChanged(state, action.id, action.patch);
    case 'actionPicked':
      return actionPicked(state, action.id, action.actionId);
    case 'fieldChanged':
      return fieldChanged(state, action.id, action.fieldId, action.value);
    case 'waitChanged':
      return waitChanged(state, action.id, action.duration);
    case 'loopChanged':
      return loopChanged(state, action.id, action.rounds);
    case 'outputAdded':
      return outputAdded(state, action.id, action.outputId);
    case 'outputRenamed':
      return outputRenamed(state, action.id, action.outputId, action.label);
    case 'outputRemoved':
      return outputRemoved(state, action.id, action.outputId);
    case 'stepReset':
      return stepReset(state, action.id);
    case 'undone':
      return undone(state);
    case 'redone':
      return redone(state);
    case 'noticeCleared':
      return noticeCleared(state, action.token);
    case 'saveStarted':
      return saveStarted(state);
    case 'saved':
      return saved(state, now);
    case 'published':
      return published(state, action.isLive);
    case 'runStarted':
      return runStarted(state, action.sampleId);
    case 'runAdvanced':
      return runAdvanced(state, action.token, action.beat);
    case 'decided':
      return decided(state, action.decision);
    case 'runCleared':
      return runCleared(state);
    case 'cuePassed':
      return cuePassed(state, action.cue);
  }
}

export function reducer(state: BuilderState, action: BuilderAction) {
  return applyAt(state, action, Date.now());
}

import { countOf } from '@/registry/ndeko/lib/words';

import { entryOf, seriesAfter, stepOfEntry } from './catalog';
import { changed, copyOf, inserted, removed } from './edits';
import { agentCountOf, placementOf, stepOf, withInside } from './flow';
import type { InsertAt, Step, Workflow } from './model';
import type { BuilderState, Notice } from './session';
import { edited } from './session-history';

function namedAs(step: Step, name: string | undefined): Step {
  if (name === undefined) {
    return step;
  }
  return { ...step, name };
}

/** A new step takes the selection, and the inspector opens on its setup. */
function arrived(
  state: BuilderState,
  step: Step,
  spoken: string
): BuilderState {
  return {
    ...state,
    selectedId: step.id,
    arrivedId: step.id,
    tab: 'setup',
    isFollowingRun: false,
    spoken,
  };
}

export function stepAdded(
  state: BuilderState,
  entryId: string,
  at: InsertAt,
  id: string,
  name: string | undefined
): BuilderState {
  const entry = entryOf(entryId);
  if (!entry) {
    return state;
  }
  const agentCount = agentCountOf(state.workflow);
  const series = seriesAfter(agentCount);
  const fresh = stepOfEntry(entry, id, series);
  const step = namedAs(fresh, name);
  let workflow = inserted(state.workflow, at, step);
  let placement = placementOf(state.workflow, at);
  const isPlaceGone = workflow === state.workflow;
  if (isPlaceGone) {
    workflow = inserted(state.workflow, { at: 'end' }, step);
    placement = placementOf(state.workflow, { at: 'end' });
  }
  const next = edited(state, workflow, null);
  return arrived(next, step, `${step.name} added ${placement}`);
}

function removedTextOf(count: number) {
  if (count === 1) {
    return 'Step removed';
  }
  const steps = countOf(count, 'step', 'steps');
  return `${steps} removed`;
}

export function stepRemoved(state: BuilderState, id: string): BuilderState {
  const step = stepOf(state.workflow, id);
  if (!step) {
    return state;
  }
  const gone = withInside(step);
  const workflow = removed(state.workflow, id);
  const next = edited(state, workflow, null);
  const noticeCount = state.noticeCount + 1;
  const notice: Notice = {
    token: noticeCount,
    text: removedTextOf(gone.length),
    canUndo: true,
    restoresId: id,
  };
  return {
    ...next,
    notice,
    noticeCount,
    spoken: `${step.name} removed. Undo is in the tool bar`,
  };
}

/** A copied agent is another agent: it takes the next series colour, never the one of its model. */
function recolored(copy: Step, workflow: Workflow): Step {
  if (copy.kind !== 'agent') {
    return copy;
  }
  const agentCount = agentCountOf(workflow);
  return { ...copy, series: seriesAfter(agentCount) };
}

export function stepDuplicated(
  state: BuilderState,
  id: string,
  copyId: string
): BuilderState {
  const step = stepOf(state.workflow, id);
  if (!step) {
    return state;
  }
  const plainCopy = copyOf(step, copyId);
  const copy = recolored(plainCopy, state.workflow);
  const after: InsertAt = { at: 'after', stepId: id };
  const workflow = inserted(state.workflow, after, copy);
  const next = edited(state, workflow, null);
  return arrived(next, copy, `${copy.name} added after ${step.name}`);
}

export function stepRenamed(
  state: BuilderState,
  id: string,
  name: string
): BuilderState {
  const workflow = changed(state.workflow, id, (step) => ({ ...step, name }));
  const next = edited(state, workflow, null);
  return { ...next, spoken: `Renamed to ${name}` };
}

export function workflowRenamed(
  state: BuilderState,
  name: string
): BuilderState {
  if (name === state.workflow.name) {
    return state;
  }
  const next = edited(state, { ...state.workflow, name }, null);
  return { ...next, spoken: `Workflow renamed to ${name}` };
}

import { stepOf } from './flow';
import type { Workflow } from './model';
import { reconciledRun } from './run';
import type { BuilderState } from './session';

const HISTORY_DEPTH = 50;

function pastAfter(state: BuilderState, continuesEdit: boolean) {
  if (continuesEdit) {
    return state.past;
  }
  const grown = [...state.past, state.workflow];
  return grown.slice(-HISTORY_DEPTH);
}

function selectedIn(workflow: Workflow, id: string | null) {
  const step = stepOf(workflow, id);
  if (!step) {
    return null;
  }
  return step.id;
}

/**
 * Every change to the flow goes through here, so Undo can walk each of them back. Edits that carry
 * the same key continue one another: a text typed key by key is one step of the history.
 */
export function edited(
  state: BuilderState,
  workflow: Workflow,
  editKey: string | null
): BuilderState {
  if (workflow === state.workflow) {
    return state;
  }
  const continuesEdit = editKey !== null && editKey === state.lastEditKey;
  return {
    ...state,
    workflow,
    past: pastAfter(state, continuesEdit),
    future: [],
    lastEditKey: editKey,
    arrivedId: null,
    notice: null,
    selectedId: selectedIn(workflow, state.selectedId),
    run: reconciledRun(state.run, workflow),
  };
}

/** A walk through the history shows the flow as it was: what was selected stays so only if it is still there. */
function walkedTo(
  state: BuilderState,
  workflow: Workflow,
  past: Workflow[],
  future: Workflow[]
): BuilderState {
  const restoredId = state.notice?.restoresId ?? state.selectedId;
  return {
    ...state,
    workflow,
    past,
    future,
    lastEditKey: null,
    arrivedId: null,
    notice: null,
    selectedId: selectedIn(workflow, restoredId),
    run: reconciledRun(state.run, workflow),
  };
}

export function undone(state: BuilderState): BuilderState {
  const previous = state.past.at(-1);
  if (!previous) {
    return state;
  }
  const past = state.past.slice(0, -1);
  const future = [state.workflow, ...state.future];
  const walked = walkedTo(state, previous, past, future);
  return { ...walked, spoken: 'Undone' };
}

export function redone(state: BuilderState): BuilderState {
  const next = state.future[0];
  if (!next) {
    return state;
  }
  const past = [...state.past, state.workflow];
  const future = state.future.slice(1);
  const walked = walkedTo(state, next, past, future);
  return { ...walked, spoken: 'Redone' };
}

import { changed, changedBranch } from './edits';
import { stepOf } from './flow';
import {
  BRANCH_MIN_OUTPUTS,
  isProductStep,
  type AgentSetup,
  type ApprovalSetup,
  type BranchOutput,
  type BranchStep,
  type LoopRounds,
  type Step,
  type WaitDuration,
} from './model';
import type { BuilderState } from './session';
import { edited } from './session-history';
import { actionOf, toolOf, valuesOf } from './tools';

export function agentChanged(
  state: BuilderState,
  id: string,
  patch: Partial<AgentSetup>
): BuilderState {
  const workflow = changed(state.workflow, id, (step) => {
    if (step.kind !== 'agent') {
      return step;
    }
    return { ...step, agent: { ...step.agent, ...patch } };
  });
  const fields = Object.keys(patch).join(' ');
  return edited(state, workflow, `agent ${id} ${fields}`);
}

export function approvalChanged(
  state: BuilderState,
  id: string,
  patch: Partial<ApprovalSetup>
): BuilderState {
  const workflow = changed(state.workflow, id, (step) => {
    if (step.kind !== 'approval') {
      return step;
    }
    return { ...step, approval: { ...step.approval, ...patch } };
  });
  return edited(state, workflow, null);
}

/** Another action has other fields: they start from what the action holds by default. */
export function actionPicked(
  state: BuilderState,
  id: string,
  actionId: string
): BuilderState {
  const workflow = changed(state.workflow, id, (step) => {
    if (!isProductStep(step)) {
      return step;
    }
    const tool = toolOf(step.tool.toolId);
    const action = actionOf(tool, actionId);
    const values = valuesOf(action);
    return { ...step, tool: { toolId: tool.id, actionId: action.id, values } };
  });
  return edited(state, workflow, null);
}

export function fieldChanged(
  state: BuilderState,
  id: string,
  fieldId: string,
  value: string
): BuilderState {
  const workflow = changed(state.workflow, id, (step) => {
    if (!isProductStep(step)) {
      return step;
    }
    const values = { ...step.tool.values, [fieldId]: value };
    return { ...step, tool: { ...step.tool, values } };
  });
  return edited(state, workflow, `field ${id} ${fieldId}`);
}

export function waitChanged(
  state: BuilderState,
  id: string,
  duration: WaitDuration
): BuilderState {
  const workflow = changed(state.workflow, id, (step) => {
    if (step.kind !== 'wait') {
      return step;
    }
    return { ...step, duration };
  });
  return edited(state, workflow, null);
}

export function loopChanged(
  state: BuilderState,
  id: string,
  rounds: LoopRounds
): BuilderState {
  const workflow = changed(state.workflow, id, (step) => {
    if (step.kind !== 'loop') {
      return step;
    }
    return { ...step, rounds };
  });
  return edited(state, workflow, null);
}

export function outputAdded(
  state: BuilderState,
  id: string,
  outputId: string
): BuilderState {
  const workflow = changedBranch(state.workflow, id, (branch) => {
    const rank = branch.outputs.length + 1;
    const output: BranchOutput = {
      id: outputId,
      label: `Output ${rank}`,
      steps: [],
    };
    return { ...branch, outputs: [...branch.outputs, output] };
  });
  const next = edited(state, workflow, null);
  return { ...next, spoken: 'Output added' };
}

function relabelled(output: BranchOutput, outputId: string, label: string) {
  if (output.id !== outputId) {
    return output;
  }
  return { ...output, label };
}

export function outputRenamed(
  state: BuilderState,
  id: string,
  outputId: string,
  label: string
): BuilderState {
  const workflow = changedBranch(state.workflow, id, (branch) => {
    const outputs = branch.outputs.map((output) =>
      relabelled(output, outputId, label)
    );
    return { ...branch, outputs };
  });
  return edited(state, workflow, `output ${id} ${outputId}`);
}

/** A branch keeps at least two outputs. The steps of the one that goes leave with it. */
export function outputRemoved(
  state: BuilderState,
  id: string,
  outputId: string
): BuilderState {
  const workflow = changedBranch(state.workflow, id, (branch) => {
    if (branch.outputs.length <= BRANCH_MIN_OUTPUTS) {
      return branch;
    }
    const outputs = branch.outputs.filter((output) => output.id !== outputId);
    return { ...branch, outputs };
  });
  const next = edited(state, workflow, null);
  return { ...next, spoken: 'Output removed' };
}

function savedLabelOf(output: BranchOutput, saved: BranchStep) {
  const match = saved.outputs.find((entry) => entry.id === output.id);
  if (!match) {
    return output;
  }
  return { ...output, label: match.label };
}

/**
 * The values of a step as they were saved. For a branch that means the labels of its outputs: the
 * steps it holds are other steps, with their own reset.
 */
function resetOf(step: Step, saved: Step): Step {
  if (step.kind !== saved.kind) {
    return step;
  }
  if (step.kind !== 'branch') {
    return saved;
  }
  if (saved.kind !== 'branch') {
    return step;
  }
  const outputs = step.outputs.map((output) => savedLabelOf(output, saved));
  return { ...step, name: saved.name, outputs };
}

function branchDiffers(step: BranchStep, saved: BranchStep) {
  if (step.name !== saved.name) {
    return true;
  }
  return step.outputs.some((output) => {
    const relabelledOutput = savedLabelOf(output, saved);
    return relabelledOutput.label !== output.label;
  });
}

/** Whether Reset has something to give back: the step was saved once and reads differently now. */
export function differsFromSaved(step: Step, saved: Step | undefined) {
  if (!saved || step === saved) {
    return false;
  }
  const areBranches = step.kind === 'branch' && saved.kind === 'branch';
  if (areBranches) {
    return branchDiffers(step, saved);
  }
  const now = JSON.stringify(step);
  const then = JSON.stringify(saved);
  return now !== then;
}

export function stepReset(state: BuilderState, id: string): BuilderState {
  const saved = stepOf(state.savedWorkflow, id);
  if (!saved) {
    return state;
  }
  const workflow = changed(state.workflow, id, (step) => resetOf(step, saved));
  const next = edited(state, workflow, null);
  return { ...next, spoken: `${saved.name} is back to its saved values` };
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';
import { restingOf } from '@/registry/ndeko/lib/run-session';

import { pressKeyOf } from './catalog';
import { DEMO_STEP } from './data';
import { nodePressKeyOf } from './flow';
import { samplePressKeyOf } from './samples';
import {
  applyAt,
  INITIAL,
  isCueOpen,
  type BuilderAction,
  type BuilderState,
  type Cue,
} from './session';

type Step = SessionStep<BuilderState, BuilderAction>;

/** The pace a person types at, the default of the library: the script has no need of a faster one. */
const KEY_MS = 42;

export const SAVE_MS = 900;

/** A request that waits on a person is answered by the demonstration after this long. */
const DEMO_DECIDES_AFTER_MS = 2500;

function hasRunOnce(state: BuilderState) {
  return state.run.token >= 1;
}

function hasRunTwice(state: BuilderState) {
  return state.run.token >= 2;
}

function hasNoRequest(state: BuilderState) {
  return state.run.phase !== 'waiting';
}

function typingSteps(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((typed, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: {
      type: 'agentChanged',
      id: DEMO_STEP.id,
      patch: { instructions: typed },
    },
  }));
}

/** The run is played by its own clock. The script waits here until the run reaches the cue. */
function waitFor(cue: Cue): Step {
  return { after: 0, action: { type: 'cuePassed', cue } };
}

function sheet(
  after: number,
  type: 'paletteSheet' | 'inspectorSheet',
  isOpen: boolean
): Step {
  return { after, by: 'demo', action: { type, isOpen } };
}

/**
 * A step is added to the Delivery branch and set up. On a narrow page the palette and the inspector
 * live in sheets, which the demonstration opens and closes as a person would.
 */
const BUILDING: Step[] = [
  {
    after: 1200,
    by: 'demo',
    press: nodePressKeyOf(DEMO_STEP.afterId),
    action: { type: 'selected', id: DEMO_STEP.afterId },
  },
  sheet(450, 'paletteSheet', true),
  {
    after: 800,
    by: 'demo',
    press: pressKeyOf(DEMO_STEP.entryId),
    action: {
      type: 'stepAdded',
      entryId: DEMO_STEP.entryId,
      at: { at: 'after', stepId: DEMO_STEP.afterId },
      id: DEMO_STEP.id,
      name: DEMO_STEP.name,
    },
  },
  sheet(350, 'paletteSheet', false),
  sheet(300, 'inspectorSheet', true),
  ...typingSteps(DEMO_STEP.instructions, 600),
  sheet(500, 'inspectorSheet', false),
  { after: 400, by: 'demo', press: 'save', action: { type: 'saveStarted' } },
  { after: SAVE_MS, action: { type: 'saved' } },
];

/**
 * Two runs: a delivery question that goes through the new step, then a refund that stops on the
 * approval. Starting a run and answering the approval are the steps of a person.
 */
const RUNNING: Step[] = [
  {
    after: 1000,
    by: 'person',
    press: 'run',
    action: { type: 'runStarted', sampleId: 'delivery' },
    isAnswered: hasRunOnce,
  },
  waitFor('reply'),
  sheet(250, 'inspectorSheet', true),
  waitFor('settled'),
  sheet(1000, 'inspectorSheet', false),
  {
    after: 1100,
    by: 'person',
    press: samplePressKeyOf('refund'),
    action: { type: 'runStarted', sampleId: 'refund' },
    isAnswered: hasRunTwice,
  },
  waitFor('settled'),
  {
    after: DEMO_DECIDES_AFTER_MS,
    by: 'person',
    press: 'allow',
    action: { type: 'decided', decision: 'approved' },
    isAnswered: hasNoRequest,
  },
  waitFor('reply'),
  sheet(250, 'inspectorSheet', true),
  waitFor('settled'),
  sheet(1000, 'inspectorSheet', false),
];

export const SCRIPT: Step[] = [...BUILDING, ...RUNNING];

function cuesOf(steps: Step[]) {
  const cues: Cue[] = [];
  for (const step of steps) {
    if (step.action.type === 'cuePassed') {
      cues.push(step.action.cue);
    }
  }
  return cues;
}

const CUES = cuesOf(SCRIPT);

/** The steps of the system hold while the run has not reached the cue the script waits for. */
export function holdsForRun(state: BuilderState) {
  const cue = CUES[state.cuesPassed] ?? 'settled';
  return !isCueOpen(state, cue);
}

const PLAYED = restingOf(INITIAL, SCRIPT, applyAt);

/** Under reduced motion the flow shows its last run finished: the Refund branch taken, the others skipped, the reply written. */
export const RESTING: BuilderState = {
  ...PLAYED,
  save: { status: 'saved', at: null },
  arrivedId: null,
  notice: null,
  spoken: '',
  isPaletteOpen: false,
  isInspectorOpen: false,
};

export const LOOP_AFTER_MS = 3600;

import { wordsOf } from '@/registry/ndeko/lib/words';

import { stepOf } from './flow';
import type { Step, Workflow } from './model';
import {
  FAILED_TRY_MS,
  resultOf,
  sampleOf,
  type Sample,
  type SampleId,
} from './samples';

export type RunPhase = 'idle' | 'running' | 'waiting' | 'done' | 'stopped';

export type StepStatus =
  'running' | 'failed' | 'retrying' | 'waiting' | 'done' | 'denied' | 'skipped';

export type Decision = 'approved' | 'denied';

export type StepRun = {
  status: StepStatus;
  ms: number;
  usd: number;
  /** One line the card shows in place of the kind: what a branch took, why a try failed. */
  note: string | null;
};

export type Beat = {
  kind: 'start' | 'finish' | 'retry';
  stepId: string;
};

export type Run = {
  /** Counts the runs, so what belongs to an earlier one can be told apart. */
  token: number;
  sampleId: SampleId;
  phase: RunPhase;
  /** Counts the beats played in this run: a timer that fires late cannot play one twice. */
  beat: number;
  next: Beat | null;
  steps: Partial<Record<string, StepRun>>;
  taken: string[];
  choices: Partial<Record<string, string>>;
  streamingId: string | null;
  decision: Decision | null;
  durationMs: number;
  costUsd: number;
};

export const WORD_MS = 45;

/** A stream is given a little longer than its words need, so its last word lands before the step ends. */
const STREAM_MARGIN_MS = 400;

const START_MS = 500;

/** The run waits this long between two steps: the time the dot takes along the edge. */
export const TRAVEL_MS = 380;

/** How long a failure stays on the card before the step tries again. */
const RETRY_AFTER_MS = 800;

/** The agent whose answer carries this name writes the email that goes back to the customer. */
const REPLY_NAME = 'reply';

export const IDLE_RUN: Run = {
  token: 0,
  sampleId: 'delivery',
  phase: 'idle',
  beat: 0,
  next: null,
  steps: {},
  taken: [],
  choices: {},
  streamingId: null,
  decision: null,
  durationMs: 0,
  costUsd: 0,
};

export function isBusy(run: Run) {
  return run.phase === 'running';
}

export function isOver(run: Run) {
  return run.phase === 'done' || run.phase === 'stopped';
}

export function hasRun(run: Run) {
  return run.phase !== 'idle';
}

export function startedRun(
  run: Run,
  workflow: Workflow,
  sampleId: SampleId
): Run {
  const token = run.token + 1;
  const fresh: Run = { ...IDLE_RUN, token, sampleId };
  const first = workflow.steps[0];
  if (!first) {
    return { ...fresh, phase: 'done' };
  }
  const next: Beat = { kind: 'start', stepId: first.id };
  return { ...fresh, phase: 'running', next };
}

/** The marks of the last run leave the canvas. The count of runs stays, so a late timer still misses. */
export function clearedRun(run: Run): Run {
  return { ...IDLE_RUN, token: run.token, sampleId: run.sampleId };
}

export function waitingIdOf(run: Run) {
  const entries = Object.entries(run.steps);
  const waiting = entries.find(([, stepRun]) => stepRun?.status === 'waiting');
  if (!waiting) {
    return null;
  }
  return waiting[0];
}

function isLive(stepRun: StepRun | undefined) {
  const status = stepRun?.status;
  const isAtWork = status === 'running' || status === 'retrying';
  return isAtWork || status === 'waiting';
}

export function liveIdOf(run: Run) {
  const entries = Object.entries(run.steps);
  const live = entries.find(([, stepRun]) => isLive(stepRun));
  if (!live) {
    return null;
  }
  return live[0];
}

/** A failed try is followed by another one: a run that stops in between leaves the step unfinished too. */
function isUnfinished(stepRun: StepRun | undefined) {
  const hasFailedTry = stepRun?.status === 'failed';
  return isLive(stepRun) || hasFailedTry;
}

/**
 * A run that stops keeps what its steps did and drops what they were still doing: nothing would ever
 * end it, and an Undo that brings the step back would show it at work or waiting for good.
 */
export function stoppedRun(run: Run): Run {
  const steps: Partial<Record<string, StepRun>> = {};
  for (const [id, stepRun] of Object.entries(run.steps)) {
    if (!isUnfinished(stepRun)) {
      steps[id] = stepRun;
    }
  }
  return { ...run, steps, phase: 'stopped', next: null, streamingId: null };
}

/** A run that waits on a step that is gone has nothing left to wait for. */
export function reconciledRun(run: Run, workflow: Workflow): Run {
  if (run.phase !== 'waiting') {
    return run;
  }
  const waitingId = waitingIdOf(run);
  const step = stepOf(workflow, waitingId);
  if (step) {
    return run;
  }
  return stoppedRun(run);
}

/** Only an agent writes prose. The others give a result with named parts. */
function textOf(step: Step, sample: Sample, decision: Decision | null) {
  if (step.kind !== 'agent') {
    return null;
  }
  if (step.agent.outputName !== REPLY_NAME) {
    const result = resultOf(sample, step);
    return result.text ?? null;
  }
  if (decision === 'denied') {
    return sample.replyIfDenied;
  }
  return sample.reply;
}

function streamMsOf(text: string) {
  const words = wordsOf(text);
  return words.length * WORD_MS + STREAM_MARGIN_MS;
}

/** A step that streams runs for as long as its text takes to arrive. */
export function tryMsOf(step: Step, sample: Sample, decision: Decision | null) {
  const result = resultOf(sample, step);
  const text = textOf(step, sample, decision);
  const isStreamed = step.kind === 'agent' && step.agent.streams;
  const followsText = isStreamed || result.ms === 0;
  if (text !== null && followsText) {
    return streamMsOf(text);
  }
  return result.ms;
}

export function failsNow(run: Run, step: Step, sample: Sample) {
  const isTheOne = sample.failure?.stepId === step.id;
  const isFirstTry = run.steps[step.id]?.status === 'running';
  return isTheOne && isFirstTry;
}

function startDelayOf(run: Run) {
  if (run.beat === 0) {
    return START_MS;
  }
  return TRAVEL_MS;
}

/** How long to wait before the next beat. Null while the run has nothing to play. */
export function delayOf(run: Run, workflow: Workflow) {
  const beat = run.next;
  if (run.phase !== 'running' || beat === null) {
    return null;
  }
  if (beat.kind === 'retry') {
    return RETRY_AFTER_MS;
  }
  if (beat.kind === 'start') {
    return startDelayOf(run);
  }
  const step = stepOf(workflow, beat.stepId);
  if (!step) {
    return 0;
  }
  const sample = sampleOf(run.sampleId);
  if (failsNow(run, step, sample)) {
    return FAILED_TRY_MS;
  }
  return tryMsOf(step, sample, run.decision);
}

export type StepExchange = {
  input: Record<string, unknown>;
  output: Record<string, unknown>;
  text: string | null;
};

/** An approval gives what the person decided, so its output is not in the recorded results. */
export function exchangeOf(run: Run, step: Step): StepExchange {
  const sample = sampleOf(run.sampleId);
  const result = resultOf(sample, step);
  const text = textOf(step, sample, run.decision);
  if (step.kind !== 'approval') {
    return { input: result.input, output: result.output, text };
  }
  const status = run.steps[step.id]?.status;
  if (status === 'done') {
    return { input: result.input, output: { decision: 'approved' }, text };
  }
  if (status === 'denied') {
    return { input: result.input, output: { decision: 'denied' }, text };
  }
  return { input: result.input, output: {}, text };
}

import { formatDuration } from '@/registry/ndeko/lib/agent-run';

import {
  edgeIdOf,
  firstOf,
  joinAfter,
  outputNamed,
  restAfter,
  stepOf,
  successorOf,
  withInside,
} from './flow';
import type { BranchOutput, BranchStep, Step, Workflow } from './model';
import {
  failsNow,
  stoppedRun,
  tryMsOf,
  waitingIdOf,
  type Beat,
  type Decision,
  type Run,
  type StepRun,
} from './run';
import { FAILED_TRY_MS, resultOf, sampleOf, type Sample } from './samples';

export type Outcome = {
  run: Run;
  /** The one line a screen reader hears about the beat. Empty when there is nothing to say. */
  spoken: string;
};

function withStep(run: Run, id: string, stepRun: StepRun): Run {
  return { ...run, steps: { ...run.steps, [id]: stepRun } };
}

function withSkipped(run: Run, skipped: Step[]): Run {
  const steps = { ...run.steps };
  for (const step of skipped) {
    steps[step.id] = { status: 'skipped', ms: 0, usd: 0, note: null };
  }
  return { ...run, steps };
}

function stopped(run: Run): Outcome {
  const ended = stoppedRun(run);
  return { run: ended, spoken: 'The run stopped: its next step was removed' };
}

/** The run takes the edge out of a step, then goes on with what it leads to or ends there. */
function handedOver(
  run: Run,
  target: Step | null,
  edgeId: string,
  spoken: string
): Outcome {
  const taken = [...run.taken, edgeId];
  if (!target) {
    const total = formatDuration(run.durationMs);
    const ended: Run = { ...run, taken, phase: 'done', next: null };
    return { run: ended, spoken: `${spoken}. Run finished in ${total}` };
  }
  const next: Beat = { kind: 'start', stepId: target.id };
  return { run: { ...run, taken, next }, spoken };
}

function streamingIdOf(step: Step) {
  const isStreamed = step.kind === 'agent' && step.agent.streams;
  if (isStreamed) {
    return step.id;
  }
  return null;
}

function startedStep(run: Run, step: Step): Outcome {
  if (step.kind === 'approval') {
    const sample = sampleOf(run.sampleId);
    const asked = sample.request?.spoken ?? step.name;
    const waiting = withStep(run, step.id, {
      status: 'waiting',
      ms: 0,
      usd: 0,
      note: 'Waiting for you',
    });
    return {
      run: { ...waiting, phase: 'waiting', next: null },
      spoken: `Waiting for you: ${asked}`,
    };
  }
  const running = withStep(run, step.id, {
    status: 'running',
    ms: 0,
    usd: 0,
    note: null,
  });
  const next: Beat = { kind: 'finish', stepId: step.id };
  const streamingId = streamingIdOf(step);
  return { run: { ...running, next, streamingId }, spoken: '' };
}

function retriedStep(run: Run, step: Step): Outcome {
  const spentMs = run.steps[step.id]?.ms ?? 0;
  const retrying = withStep(run, step.id, {
    status: 'retrying',
    ms: spentMs,
    usd: 0,
    note: 'Trying again',
  });
  const next: Beat = { kind: 'finish', stepId: step.id };
  return { run: { ...retrying, next }, spoken: '' };
}

function failedStep(run: Run, step: Step, sample: Sample): Outcome {
  const error = sample.failure?.error ?? 'It did not answer';
  const failed = withStep(run, step.id, {
    status: 'failed',
    ms: FAILED_TRY_MS,
    usd: 0,
    note: error,
  });
  const next: Beat = { kind: 'retry', stepId: step.id };
  return {
    run: { ...failed, next },
    spoken: `${step.name} failed: ${error}. Trying again`,
  };
}

function doneNoteOf(step: Step, wasRetried: boolean) {
  if (wasRetried) {
    return 'Done on the second try';
  }
  if (step.kind === 'wait') {
    return 'A test run does not wait';
  }
  if (step.kind === 'loop') {
    return 'A test run plays it once';
  }
  return null;
}

function insideOfOutput(output: BranchOutput) {
  return output.steps.flatMap(withInside);
}

/** A branch takes the output that carries the topic of the sample, or its last one when none does. */
function routed(
  run: Run,
  workflow: Workflow,
  branch: BranchStep,
  sample: Sample
): Outcome {
  const named = outputNamed(branch, sample.topic);
  const output = named ?? branch.outputs.at(-1);
  if (!output) {
    return stopped(run);
  }
  const others = branch.outputs.filter((other) => other.id !== output.id);
  const leftOut = others.flatMap(insideOfOutput);
  const skipped = withSkipped(run, leftOut);
  const spentMs = skipped.steps[branch.id]?.ms ?? 0;
  const noted = withStep(skipped, branch.id, {
    status: 'done',
    ms: spentMs,
    usd: 0,
    note: `Took ${output.label}`,
  });
  const choices = { ...noted.choices, [branch.id]: output.id };
  const target = firstOf(workflow, branch, output);
  const edgeId = edgeIdOf(branch.id, output.id);
  const spoken = `${branch.name} took ${output.label}`;
  return handedOver({ ...noted, choices }, target, edgeId, spoken);
}

function finishedStep(run: Run, workflow: Workflow, step: Step): Outcome {
  const sample = sampleOf(run.sampleId);
  if (failsNow(run, step, sample)) {
    return failedStep(run, step, sample);
  }
  const before = run.steps[step.id];
  const wasRetried = before?.status === 'retrying';
  const spentMs = before?.ms ?? 0;
  const result = resultOf(sample, step);
  const tryMs = tryMsOf(step, sample, run.decision);
  const ms = spentMs + tryMs;
  const done = withStep(run, step.id, {
    status: 'done',
    ms,
    usd: result.usd,
    note: doneNoteOf(step, wasRetried),
  });
  const counted: Run = {
    ...done,
    streamingId: null,
    durationMs: run.durationMs + ms,
    costUsd: run.costUsd + result.usd,
  };
  if (step.kind === 'branch') {
    return routed(counted, workflow, step, sample);
  }
  const target = successorOf(workflow, step.id);
  const edgeId = edgeIdOf(step.id, null);
  const spoken = `${step.name} done in ${formatDuration(ms)}`;
  return handedOver(counted, target, edgeId, spoken);
}

export function advancedRun(run: Run, workflow: Workflow): Outcome {
  const beat = run.next;
  if (run.phase !== 'running' || beat === null) {
    return { run, spoken: '' };
  }
  const played: Run = { ...run, beat: run.beat + 1 };
  const step = stepOf(workflow, beat.stepId);
  if (!step) {
    return stopped(played);
  }
  if (beat.kind === 'start') {
    return startedStep(played, step);
  }
  if (beat.kind === 'retry') {
    return retriedStep(played, step);
  }
  return finishedStep(played, workflow, step);
}

/**
 * Allow lets the run go on. Deny stops its branch there: what was left of the branch is skipped and
 * the run goes on from the step where the branches join, or ends when the approval sat on the trunk.
 */
export function decidedRun(
  run: Run,
  workflow: Workflow,
  decision: Decision
): Outcome {
  if (run.phase !== 'waiting') {
    return { run, spoken: '' };
  }
  const waitingId = waitingIdOf(run);
  const step = stepOf(workflow, waitingId);
  if (!step) {
    return stopped(run);
  }
  const answered: Run = { ...run, phase: 'running', decision };
  if (decision === 'approved') {
    const allowed = withStep(answered, step.id, {
      status: 'done',
      ms: 0,
      usd: 0,
      note: 'Allowed by you',
    });
    const target = successorOf(workflow, step.id);
    const edgeId = edgeIdOf(step.id, null);
    return handedOver(allowed, target, edgeId, 'Allowed by you');
  }
  const denied = withStep(answered, step.id, {
    status: 'denied',
    ms: 0,
    usd: 0,
    note: 'Denied by you',
  });
  const leftOut = restAfter(workflow, step.id);
  const skipped = withSkipped(denied, leftOut);
  const target = joinAfter(workflow, step.id);
  if (!target) {
    const ended: Run = { ...skipped, phase: 'stopped', next: null };
    return { run: ended, spoken: 'Denied. The run stops here' };
  }
  const next: Beat = { kind: 'start', stepId: target.id };
  return {
    run: { ...skipped, next },
    spoken:
      'Denied. The branch stops here and the reply says a person will follow up',
  };
}

import {
  isProductStep,
  type BranchOutput,
  type BranchStep,
  type InsertAt,
  type Step,
  type Workflow,
} from './model';

/** A step with its place in the flow: its rank when the flow is read from top to bottom, the outputs of a branch left to right. */
export type Placed = {
  step: Step;
  position: number;
  /** The label of the nearest output of a branch that holds the step. */
  branchLabel: string | null;
};

type Hold = {
  list: Step[];
  index: number;
};

function visit(steps: Step[], branchLabel: string | null, into: Placed[]) {
  for (const step of steps) {
    const position = into.length + 1;
    into.push({ step, position, branchLabel });
    if (step.kind !== 'branch') {
      continue;
    }
    for (const output of step.outputs) {
      visit(output.steps, output.label, into);
    }
  }
}

export function walkOf(workflow: Workflow) {
  const placed: Placed[] = [];
  visit(workflow.steps, null, placed);
  return placed;
}

export function withInside(step: Step) {
  const placed: Placed[] = [];
  visit([step], null, placed);
  return placed.map((entry) => entry.step);
}

function trailIn(list: Step[], id: string): Hold[] | null {
  for (const [index, step] of list.entries()) {
    if (step.id === id) {
      return [{ list, index }];
    }
    if (step.kind !== 'branch') {
      continue;
    }
    for (const output of step.outputs) {
      const inner = trailIn(output.steps, id);
      if (inner) {
        return [{ list, index }, ...inner];
      }
    }
  }
  return null;
}

/** The lists that hold a step, from the flow itself down to the list the step sits in. */
function trailOf(workflow: Workflow, id: string) {
  return trailIn(workflow.steps, id);
}

export function stepOf(workflow: Workflow, id: string | null) {
  if (id === null) {
    return undefined;
  }
  const placed = walkOf(workflow);
  const found = placed.find((entry) => entry.step.id === id);
  return found?.step;
}

function branchOf(workflow: Workflow, id: string) {
  const step = stepOf(workflow, id);
  if (step?.kind !== 'branch') {
    return undefined;
  }
  return step;
}

/** The output of a branch whose label reads like `label`, whatever its case. */
export function outputNamed(branch: BranchStep, label: string) {
  const wanted = label.trim().toLowerCase();
  return branch.outputs.find((output) => {
    const own = output.label.trim().toLowerCase();
    return own === wanted;
  });
}

/** What runs once a step is over: the next one of its list, or the one after the branch that holds it. */
function afterOf(trail: Hold[]) {
  for (let depth = trail.length - 1; depth >= 0; depth -= 1) {
    const hold = trail[depth];
    const next = hold.list[hold.index + 1];
    if (next) {
      return next;
    }
  }
  return null;
}

export function successorOf(workflow: Workflow, id: string) {
  const trail = trailOf(workflow, id);
  if (!trail) {
    return null;
  }
  return afterOf(trail);
}

/** What runs once the whole list that holds a step is over: the step where its branch joins, if it sits in one. */
export function joinAfter(workflow: Workflow, id: string) {
  const trail = trailOf(workflow, id);
  if (!trail) {
    return null;
  }
  const outer = trail.slice(0, -1);
  return afterOf(outer);
}

/** An empty output hands over at once to the step where the outputs join. */
export function firstOf(
  workflow: Workflow,
  branch: BranchStep,
  output: BranchOutput
) {
  const first = output.steps[0];
  if (first) {
    return first;
  }
  return successorOf(workflow, branch.id);
}

/** The steps after `id` in its own list, with all they hold. They are what a denied approval leaves out. */
export function restAfter(workflow: Workflow, id: string) {
  const trail = trailOf(workflow, id);
  const hold = trail?.at(-1);
  if (!hold) {
    return [];
  }
  const rest = hold.list.slice(hold.index + 1);
  return rest.flatMap(withInside);
}

/**
 * Every step that has run when `id` starts: what comes before it in each list that holds it. The
 * other outputs of its own branch are left out, since they never run in the same pass.
 */
export function upstreamOf(workflow: Workflow, id: string) {
  const trail = trailOf(workflow, id);
  if (!trail) {
    return [];
  }
  const ids = new Set<string>();
  for (const hold of trail) {
    const earlier = hold.list.slice(0, hold.index);
    const steps = earlier.flatMap(withInside);
    for (const step of steps) {
      ids.add(step.id);
    }
  }
  const placed = walkOf(workflow);
  return placed.filter((entry) => ids.has(entry.step.id));
}

export function previousOf(workflow: Workflow, id: string) {
  const placed = walkOf(workflow);
  const index = placed.findIndex((entry) => entry.step.id === id);
  if (index <= 0) {
    return null;
  }
  return placed[index - 1].step;
}

export function countsOf(workflow: Workflow) {
  const placed = walkOf(workflow);
  let branches = 0;
  for (const entry of placed) {
    if (entry.step.kind === 'branch') {
      branches += entry.step.outputs.length;
    }
  }
  return { steps: placed.length, branches };
}

export function agentCountOf(workflow: Workflow) {
  const placed = walkOf(workflow);
  const agents = placed.filter((entry) => entry.step.kind === 'agent');
  return agents.length;
}

export function nodePressKeyOf(stepId: string) {
  return `node-${stepId}`;
}

/** A step has one way out, a branch one for each output: that is enough to name an edge. */
export function edgeIdOf(fromId: string, outputId: string | null) {
  if (outputId === null) {
    return fromId;
  }
  return `${fromId}:${outputId}`;
}

/** The label each output of a branch carries on its edge, by the id of that edge. */
export function outputLabelsOf(workflow: Workflow) {
  const labels: Record<string, string> = {};
  for (const { step } of walkOf(workflow)) {
    if (step.kind !== 'branch') {
      continue;
    }
    for (const output of step.outputs) {
      const edgeId = edgeIdOf(step.id, output.id);
      labels[edgeId] = output.label;
    }
  }
  return labels;
}

type KeyPart = string | number | KeyPart[];

function shapeOfStep(step: Step): KeyPart[] {
  if (step.kind !== 'branch') {
    return [step.id, step.kind];
  }
  const outputs = step.outputs.map(shapeOfOutput);
  return [step.id, step.kind, outputs];
}

function shapeOfOutput(output: BranchOutput): KeyPart[] {
  const steps = output.steps.map(shapeOfStep);
  return [output.id, steps];
}

/** What the layout reads: the ids, the kinds, the outputs of each branch and their order. Never a name or a setting. */
export function structureKeyOf(workflow: Workflow) {
  const steps = workflow.steps.map(shapeOfStep);
  return JSON.stringify(steps);
}

function pictureOf(step: Step): KeyPart[] {
  if (step.kind === 'agent') {
    return [step.seed, step.series];
  }
  if (isProductStep(step)) {
    return [step.tool.toolId];
  }
  return [];
}

function faceOfStep(step: Step): KeyPart[] {
  const picture = pictureOf(step);
  const face: KeyPart[] = [step.id, step.kind, step.name, picture];
  if (step.kind === 'branch') {
    const outputs = step.outputs.map(faceOfOutput);
    face.push(outputs);
  }
  return face;
}

function faceOfOutput(output: BranchOutput): KeyPart[] {
  const steps = output.steps.map(faceOfStep);
  return [output.id, output.label, steps];
}

/**
 * What the canvas shows: the structure, the names, the pictures and the labels of the outputs.
 * Instructions and the other settings are not in it, so typing them leaves the canvas as it is.
 */
export function faceKeyOf(workflow: Workflow) {
  const steps = workflow.steps.map(faceOfStep);
  return JSON.stringify([workflow.name, steps]);
}

const AT_THE_END = 'at the end of the flow';

/** Where a new step would go, in words that follow "Add a step": after Track the parcel, first in Refund. */
export function placementOf(workflow: Workflow, at: InsertAt) {
  if (at.at === 'end') {
    return AT_THE_END;
  }
  if (at.at === 'first') {
    const branch = branchOf(workflow, at.branchId);
    const output = branch?.outputs.find((entry) => entry.id === at.outputId);
    const label = output?.label ?? 'this output';
    return `first in ${label}`;
  }
  const step = stepOf(workflow, at.stepId);
  if (!step) {
    return AT_THE_END;
  }
  if (step.kind === 'branch') {
    return `where the outputs of ${step.name} join`;
  }
  return `after ${step.name}`;
}

import type {
  BranchOutput,
  BranchStep,
  InsertAt,
  Step,
  Workflow,
} from './model';

type ListEdit = (list: Step[], index: number) => Step[];

/** Every list and step an edit does not touch keeps its identity, so only what changed is drawn again. */
function editedWhereHeld(steps: Step[], id: string, edit: ListEdit): Step[] {
  const index = steps.findIndex((step) => step.id === id);
  if (index >= 0) {
    return edit(steps, index);
  }
  let hasChanged = false;
  const next = steps.map((step) => {
    const edited = editedInside(step, id, edit);
    if (edited !== step) {
      hasChanged = true;
    }
    return edited;
  });
  if (!hasChanged) {
    return steps;
  }
  return next;
}

function editedInside(step: Step, id: string, edit: ListEdit): Step {
  if (step.kind !== 'branch') {
    return step;
  }
  let hasChanged = false;
  const outputs = step.outputs.map((output) => {
    const steps = editedWhereHeld(output.steps, id, edit);
    if (steps === output.steps) {
      return output;
    }
    hasChanged = true;
    return { ...output, steps };
  });
  if (!hasChanged) {
    return step;
  }
  return { ...step, outputs };
}

function withSteps(workflow: Workflow, steps: Step[]): Workflow {
  if (steps === workflow.steps) {
    return workflow;
  }
  return { ...workflow, steps };
}

export function changed(
  workflow: Workflow,
  id: string,
  change: (step: Step) => Step
) {
  const steps = editedWhereHeld(workflow.steps, id, (list, index) => {
    const next = change(list[index]);
    if (next === list[index]) {
      return list;
    }
    const copy = [...list];
    copy[index] = next;
    return copy;
  });
  return withSteps(workflow, steps);
}

export function removed(workflow: Workflow, id: string) {
  const steps = editedWhereHeld(workflow.steps, id, (list, index) => {
    const before = list.slice(0, index);
    const after = list.slice(index + 1);
    return [...before, ...after];
  });
  return withSteps(workflow, steps);
}

function insertedAfter(workflow: Workflow, stepId: string, step: Step) {
  const steps = editedWhereHeld(workflow.steps, stepId, (list, index) => {
    const before = list.slice(0, index + 1);
    const after = list.slice(index + 1);
    return [...before, step, ...after];
  });
  return withSteps(workflow, steps);
}

function withFirst(output: BranchOutput, outputId: string, step: Step) {
  if (output.id !== outputId) {
    return output;
  }
  return { ...output, steps: [step, ...output.steps] };
}

function insertedFirst(
  workflow: Workflow,
  branchId: string,
  outputId: string,
  step: Step
) {
  return changed(workflow, branchId, (branch) => {
    if (branch.kind !== 'branch') {
      return branch;
    }
    const hasOutput = branch.outputs.some((output) => output.id === outputId);
    if (!hasOutput) {
      return branch;
    }
    const outputs = branch.outputs.map((output) =>
      withFirst(output, outputId, step)
    );
    return { ...branch, outputs };
  });
}

export function inserted(workflow: Workflow, at: InsertAt, step: Step) {
  if (at.at === 'after') {
    return insertedAfter(workflow, at.stepId, step);
  }
  if (at.at === 'first') {
    return insertedFirst(workflow, at.branchId, at.outputId, step);
  }
  return withSteps(workflow, [...workflow.steps, step]);
}

/** Copies never share an id with what they come from: the copy takes the base, what it holds the base and a rank. */
type IdMint = { base: string; count: number };

function mintedId(mint: IdMint) {
  const rank = mint.count;
  mint.count += 1;
  if (rank === 0) {
    return mint.base;
  }
  return `${mint.base}-${rank}`;
}

function copiedOutput(output: BranchOutput, mint: IdMint): BranchOutput {
  const id = mintedId(mint);
  const steps = output.steps.map((step) => copiedStep(step, mint));
  return { ...output, id, steps };
}

function copiedStep(step: Step, mint: IdMint): Step {
  const id = mintedId(mint);
  if (step.kind === 'branch') {
    const outputs = step.outputs.map((output) => copiedOutput(output, mint));
    return { ...step, id, outputs };
  }
  if (step.kind === 'agent') {
    return { ...step, id, seed: id };
  }
  return { ...step, id };
}

export function copyOf(step: Step, idBase: string): Step {
  const mint: IdMint = { base: idBase, count: 0 };
  const copy = copiedStep(step, mint);
  return { ...copy, name: `${step.name} copy` };
}

export function changedBranch(
  workflow: Workflow,
  id: string,
  change: (branch: BranchStep) => BranchStep
) {
  return changed(workflow, id, (step) => {
    if (step.kind !== 'branch') {
      return step;
    }
    return change(step);
  });
}

import type { SeriesSlot } from '@/registry/ndeko/lib/agent-run';

export type ToolId =
  | 'gmail'
  | 'stripe'
  | 'linear'
  | 'notion'
  | 'github'
  | 'googledrive'
  | 'shopify'
  | 'airtable'
  | 'zendesk'
  | 'calder';

export type ModelId =
  'claude-haiku' | 'claude-sonnet' | 'gpt-mini' | 'gemini-flash';

export type PersonId = 'maren' | 'idris' | 'lotte';

export type StepKind =
  | 'trigger'
  | 'agent'
  | 'branch'
  | 'approval'
  | 'tool'
  | 'output'
  | 'wait'
  | 'loop';

export const KIND_WORD: Record<StepKind, string> = {
  trigger: 'Trigger',
  agent: 'Agent',
  branch: 'Branch',
  approval: 'Approval',
  tool: 'Tool',
  output: 'Output',
  wait: 'Wait',
  loop: 'Loop',
};

/** A value may name what an earlier step gave, between braces: {{order.id}}. */
export type ToolSetup = {
  toolId: ToolId;
  actionId: string;
  values: Record<string, string>;
};

export type Creativity = 'precise' | 'balanced' | 'creative';

export type AgentSetup = {
  instructions: string;
  modelId: ModelId;
  creativity: Creativity;
  streams: boolean;
  remembers: boolean;
  retries: boolean;
  outputName: string;
  /** The parts of a structured answer, read as {{topic.order}}. Empty when the agent writes plain text. */
  outputParts: string[];
};

export type TimeoutHours = '1' | '4' | '24';

export type TimeoutRule = 'deny' | 'wait' | 'escalate';

export type ApprovalSetup = {
  approverId: PersonId;
  timeoutHours: TimeoutHours;
  onTimeout: TimeoutRule;
};

export type WaitDuration = '5m' | '1h' | '1d';

export type LoopRounds = '2' | '3' | '5';

type StepBase = {
  id: string;
  name: string;
};

export type TriggerStep = StepBase & {
  kind: 'trigger';
  tool: ToolSetup;
};

export type AgentStep = StepBase & {
  kind: 'agent';
  /** What its picture is drawn from. It stays the same when the step is renamed. */
  seed: string;
  series: SeriesSlot;
  agent: AgentSetup;
};

export type BranchOutput = {
  id: string;
  label: string;
  steps: Step[];
};

export type BranchStep = StepBase & {
  kind: 'branch';
  outputs: BranchOutput[];
};

export type ApprovalStep = StepBase & {
  kind: 'approval';
  approval: ApprovalSetup;
};

export type ToolStep = StepBase & {
  kind: 'tool';
  tool: ToolSetup;
};

export type OutputStep = StepBase & {
  kind: 'output';
  tool: ToolSetup;
};

export type WaitStep = StepBase & {
  kind: 'wait';
  duration: WaitDuration;
};

export type LoopStep = StepBase & {
  kind: 'loop';
  rounds: LoopRounds;
};

export type Step =
  | TriggerStep
  | AgentStep
  | BranchStep
  | ApprovalStep
  | ToolStep
  | OutputStep
  | WaitStep
  | LoopStep;

export type ProductStep = TriggerStep | ToolStep | OutputStep;

/** A flow runs downwards. The outputs of a branch run side by side, then join at the step after it. */
export type Workflow = {
  id: string;
  name: string;
  steps: Step[];
};

/** Where a new step goes: after a step of the same list, first in an output of a branch, or at the end of the flow. */
export type InsertAt =
  | { at: 'after'; stepId: string }
  | { at: 'first'; branchId: string; outputId: string }
  | { at: 'end' };

export const BRANCH_MIN_OUTPUTS = 2;

export function isProductStep(step: Step): step is ProductStep {
  const isTrigger = step.kind === 'trigger';
  const isTool = step.kind === 'tool';
  const isOutput = step.kind === 'output';
  return isTrigger || isTool || isOutput;
}

