};

export const GROUPS: PaletteGroup[] = ['models', 'logic', 'tools'];

function entryOfModel(model: Model): PaletteEntry {
  return {
    id: `model-${model.id}`,
    group: 'models',
    label: model.name,
    modelId: model.id,
  };
}

function entryOfTool(tool: Tool): PaletteEntry {
  return {
    id: `tool-${tool.id}`,
    group: 'tools',
    label: tool.name,
    toolId: tool.id,
  };
}

